from __future__ import annotations

# Key format: (domain_id, module_title)
MODULE_PRIMERS: dict[tuple[int, str], str] = {
    # 06 OS / Linux
    (6, 'OSの役割とシステムコール'): 'OSはCPU、メモリ、デバイスを直接触る特権コードをカーネルへ集約し、アプリにはプロセス、仮想メモリ、ファイル、ソケットという安全な抽象を提供します。システムコールはユーザー空間からカーネル空間へ入るABI上の入口で、通常の関数呼び出しより高い境界コストと権限検査を伴います。性能問題では呼び出し回数、コピー、コンテキスト切替を、セキュリティでは引数検証と権限境界を確認します。',
    (6, 'プロセスとスレッド'): 'プロセスは独立した仮想アドレス空間とOS資源を持つ隔離単位で、スレッドは同じプロセス内のメモリを共有する実行単位です。forkはアドレス空間をcopy-on-writeで複製し、execは現在のプロセス像を別プログラムへ置き換えます。スケジューラは実行可能なタスクをCPUへ割り当てるため、CPU affinity、優先度、コンテキストスイッチ、共有状態の競合が性能と正しさを左右します。',
    (6, '仮想メモリ'): '仮想メモリは各プロセスに連続した独自アドレス空間があるように見せ、ページテーブルで物理メモリやファイルへ写像します。未割当ページへ初めて触れるとページフォルトが発生し、copy-on-write、mmap、ページキャッシュなどを通じて必要な時だけ物理資源が割り当てられます。RSS、VSS、major/minor fault、swap、TLB missを区別すると、単純な「メモリ不足」より正確に診断できます。',
    (6, 'ファイルシステム'): 'Linuxのファイルはinodeがメタデータとデータブロックへの参照を持ち、ディレクトリは名前からinodeへの対応を管理します。VFSはext4、XFS、tmpfsなど異なる実装へ共通APIを提供し、ページキャッシュとwritebackが読み書きを遅延・集約します。クラッシュ整合性ではjournaling、fsync、renameの保証範囲を理解し、アプリの永続化完了とwrite呼び出し完了を同一視しないことが重要です。',
    (6, 'Linux I/O'): 'blocking I/Oは完了までスレッドを待たせ、non-blocking I/Oは即座に戻って準備状態を別途監視します。select/pollは監視集合を毎回走査しますが、epollはカーネル側でready集合を管理し、多数接続で効率化します。io_uringは提出・完了キューを共有メモリで扱いシステムコールとコピーを減らせますが、キュー深度、backpressure、キャンセル、ファイル種別ごとの実装差を確認する必要があります。',
    (6, 'シグナル・IPC・同期'): 'signalは非同期通知であり、ハンドラ内で安全に呼べる関数が限られます。pipeやsocket pairはバイト列、shared memoryはコピーを抑えた共有領域を提供しますが、後者には別途同期が必要です。futexは競合しない場合をユーザー空間で処理し、待ちが必要な場合だけカーネルへ入るため、mutexなど多くの同期プリミティブの基盤になります。',
    (6, 'Linux管理と観測'): '/procはプロセスやカーネル状態、/sysはデバイスとカーネルオブジェクトをファイルとして公開します。systemdはサービス依存、起動、監視、ログ連携を管理し、namespacesは見える資源、cgroupsは使える資源を制限します。障害時はtopだけで結論を出さず、pidstat、vmstat、iostat、ss、journalctl、procfsを組み合わせてCPU、待ち、メモリ、I/O、接続の証拠を時系列で集めます。',
    (6, 'シェルとCLIシステム運用'): 'シェルはコマンド実行だけでなく、標準入力・出力・エラー、終了コード、パイプ、リダイレクトを組み合わせるデータフロー言語です。安全なスクリプトでは引用、空白を含む値、glob、失敗伝播、temporary file、signal cleanupを扱います。人間向け表示と機械向け出力を分け、冪等性、dry-run、監査ログを備えると運用事故を減らせます。',
    (6, 'カーネルネットワークとストレージ'): 'ネットワークではNICから割り込み/NAPI、socket buffer、プロトコルスタックを経てアプリへデータが届きます。ストレージではVFS、ページキャッシュ、block layer、device queueを経由し、writebackとI/O schedulerが順序と集約を調整します。アプリの遅延を理解するにはユーザー空間だけでなく、run queue、softirq、socket buffer、dirty page、device latencyまで経路を追います。',
    (6, 'システムプログラミング実践'): 'システムプログラミングはsyscall、メモリ、ファイル記述子、プロセス、権限を直接扱うため、資源解放と境界検証が中心課題です。ptraceはプロセスを停止・観察し、eBPFは検証済みプログラムをカーネル内イベントへ安全に接続します。rootを常用せずLinux capabilityで必要権限だけを付与し、C/FFI境界では所有権、長さ、アラインメント、エラー規約を明示します。',

    # 09 Compiler / Interpreter / Runtime
    (9, 'コンパイラ全体像'): 'コンパイラはソースを直接機械語へ変える一枚岩ではなく、字句・構文・意味解析を行うfront-end、言語非依存の最適化を行うmiddle-end、命令選択やレジスタ割当を行うback-endに分かれます。AOTは実行前に、JITは実行時のプロファイルを使ってコードを生成します。どの段階でも「意味を保った変換」であることが中心的な不変条件です。',
    (9, '字句解析'): '字句解析は文字列をidentifier、number、keyword、operatorなどのtoken列へ変換します。正規言語として表せる規則はDFAへ変換でき、最長一致やkeyword判定を加えて実装します。位置情報、コメント、Unicode、エラー時の回復をtokenへ保持すると、後段の診断品質が上がります。',
    (9, '構文解析'): '構文解析はtoken列が文法に従うかを確認し、演算子優先順位や結合規則を反映した構文木を作ります。recursive descentは理解しやすく、LR系は広い文法を機械的に扱えます。実用パーサでは正しい入力だけでなく、同期tokenを使ったerror recoveryにより一つの誤りで解析全体を諦めない設計が重要です。',
    (9, 'AST・意味解析・型検査'): 'ASTは不要な括弧や区切りを省き、プログラムの意味構造を表します。意味解析ではscopeとsymbol tableを使って名前解決し、型検査では演算や呼び出しが型規則を満たすか確認します。同名変数のshadowing、循環参照、overload、generic inferenceなどは、単純な木走査を越えた環境管理を必要とします。',
    (9, '中間表現'): 'IRはソース言語と機械語の間に置く、解析・変換しやすい表現です。CFGは基本ブロック間の制御遷移を表し、SSAでは各変数が一度だけ代入されるため定義使用関係が明確になります。IRの抽象度を複数段階に分けると、高水準の意味最適化と低水準の機械最適化を両立できます。',
    (9, '最適化'): '最適化は実行結果を変えずに時間、空間、電力などを改善する変換です。constant folding、dead code elimination、inlining、loop invariant code motionなどは、aliasや副作用の解析が不正確だと誤コンパイルを起こします。性能向上量だけでなく、コードサイズ、コンパイル時間、デバッグ容易性、deoptimization可能性も比較します。',
    (9, 'コード生成'): 'コード生成ではIRの操作を対象ISAの命令列へ選択し、有限個のレジスタへ値を割り当て、calling conventionとstack frameを守ります。spillが増えるとメモリアクセスが増え、分岐や命令スケジューリングはCPUパイプラインへ影響します。正しさはABI、アラインメント、callee/caller-saved register、例外・unwind情報まで含みます。',
    (9, 'InterpreterとVM'): 'tree-walk interpreterはASTを直接評価して実装が簡単ですが、node dispatchと高水準構造の処理コストが大きくなります。bytecode VMはASTを小さな命令列へ変換し、stack VMやregister VM上でdispatchします。命令粒度、dispatch方式、inline cache、GC連携が速度と実装複雑性を決めます。',
    (9, 'JITとプロファイル誘導最適化'): 'JITは実行中にhot pathや実際の型を観測し、一般性を一時的に捨てた高速コードを生成します。inline cacheは呼び出し先やproperty shapeを記録し、仮定が崩れたらdeoptimizationで安全なコードへ戻します。起動時間、最適化コスト、code cache、warm-up、予測不能なtail latencyを含めて評価します。',
    (9, 'Runtime・GC・Linker・Loader'): 'runtimeはobject layout、例外、thread、GCなど言語機能の実行時支援を担います。GCは到達可能性を基に不要objectを回収し、mark-sweep、copying、generational、concurrentなどでpauseとthroughputを調整します。linkerとloaderはsymbolを解決し、再配置と共有libraryのmappingを行うため、ABI互換性とdynamic linkingの安全性が重要です。',

    # 10 Network / HTTP
    (10, 'OSI・TCP/IPモデル'): 'OSIは通信機能を7層へ整理する参照モデル、TCP/IPはInternetで実際に使われるprotocol suiteの見方です。送信側では上位データへ各層のheaderを付けるencapsulation、受信側では逆に外します。障害解析では「名前解決か、経路か、transport接続か、TLSか、HTTP semanticsか」を層ごとに切り分けます。',
    (10, 'Ethernet・ARP・VLAN'): 'Ethernet frameは同一L2 network内でMAC addressを使って配送され、switchは送信元MACから転送表を学習します。IPv4のARP、IPv6のNeighbor DiscoveryはIP addressからlink-layer addressを解決します。VLANは同じ物理switch上に論理的なbroadcast domainを分離し、taggingとtrunkで複数VLANを運びます。',
    (10, 'IP・ルーティング'): 'IPはbest-effortのpacket deliveryを提供し、routerはdestination prefixに最長一致するrouteを選びます。subnet mask/CIDRはnetworkとhost部分を分け、ICMPは到達不能やTTL超過などの制御情報を伝えます。MTU、fragmentation、asymmetric route、NAT、IPv6移行は実運用で障害原因になりやすい点です。',
    (10, 'TCP・UDP'): 'TCPはconnection-orientedなbyte streamで、sequence number、ACK、再送、flow control、congestion controlにより順序と信頼性を提供します。UDPは独立datagramを低いoverheadで送りますが、順序・再送・輻輳制御はアプリ側の責任です。TCPでもapplication message boundaryは保持されないため、length prefixやdelimiterなどのframingが必要です。',
    (10, 'DNS'): 'DNSは階層的で分散した名前データベースです。stub resolverからrecursive resolverへ問い合わせ、必要に応じてroot、TLD、authoritative serverを辿り、結果をTTL期間cacheします。negative cache、split-horizon、CNAME chain、DNSSEC、resolver障害を理解すると「IP直打ちなら動く」問題を正確に扱えます。',
    (10, 'HTTP/1.1'): 'HTTPはrequest method、target、header、bodyと、status、header、bodyからなるapplication protocolです。GET/HEADの安全性、PUT/DELETEの冪等性、cache control、conditional request、content negotiationはAPI設計へ直結します。HTTP/1.1のpersistent connectionは接続再利用を可能にしますが、同一接続上のhead-of-line問題やbody未読による再利用不能に注意します。',
    (10, 'HTTP/2・HTTP/3・QUIC'): 'HTTP/2は一つのTCP connection上で複数streamを多重化し、headerをHPACKで圧縮しますが、packet loss時にはTCP層のhead-of-line blockingが全streamへ影響します。HTTP/3はQUIC上でstreamごとの損失回復を行い、TLS 1.3を統合します。0-RTTは再接続を速めますがreplay可能性があるため非冪等操作へ無条件に使えません。',
    (10, 'TLS・PKI'): 'TLS handshakeはprotocol version、cipher、鍵交換を合意し、server certificateをPKIのtrust chainで検証してsession keyを確立します。現代的なephemeral key exchangeは長期秘密鍵が後で漏れても過去通信を復号しにくいforward secrecyを提供します。hostname、期限、revocation、trust store、SNI、mTLSを区別して診断します。',
    (10, 'Proxy・Load Balancer・CDN'): 'forward proxyはclient側の代理、reverse proxyはserver側の入口です。L4 load balancerはtransport情報、L7はHTTP host/path/header等を見て振り分けられます。CDNはedgeでcacheしorigin負荷と距離を減らしますが、cache key、Vary、認証data、purge、stale response、health checkの設計が正しさを左右します。',
    (10, 'ネットワーク観測とトラブルシュート'): 'ネットワーク診断は推測ではなく、名前解決結果、route、socket状態、packet capture、application logを同じ時刻で関連付けます。tcpdump/WiresharkではSYN/ACK、再送、window、RST、TLS alert、HTTP frameを確認し、tracerouteはTTL超過応答から経路の一部を推定します。packet loss、latency、jitter、MTU、server処理時間を分離することが重要です。',

    # 11 JS/TS/Node
    (11, 'JavaScript言語モデル'): 'JavaScriptの変数解決はlexical environmentのchainを辿り、closureは関数作成時の外側環境への参照を保持します。objectのproperty lookupはprototype chainを辿り、thisは関数の定義位置ではなく主に呼び出し形式で決まります。class構文もprototype上の仕組みを覆うsyntaxであるため、property descriptor、getter、private fieldとの違いを理解します。',
    (11, '非同期JavaScript'): 'Promiseのthen/catch/finally callbackはmicrotask queueへ入り、timerやI/O callbackなどのtaskより先に現在のturn終了後に処理されます。async/awaitはPromise chainを逐次風に書く構文で、CPU処理を別threadへ移すものではありません。timeout、AbortSignal、並列数制限、Promise.allのfail-fast、未処理rejectionを含めて制御します。',
    (11, 'TypeScript型システム'): 'TypeScriptは名前ではなくshapeで互換性を判断するstructural typingを採用します。unionをtypeof、in、discriminantなどでnarrowingし、intersectionで複数constraintを同時に満たす型を作ります。ただし型はcompile時に消え、any、type assertion、外部input、varianceの緩さなどsoundness boundaryがあるため、runtime validationと組み合わせます。',
    (11, '高度なTypeScript'): 'conditional typeは型関係に応じて結果型を分岐し、mapped typeはkey集合を反復してpropertyを変換します。inferはconditional type内で部分型を抽出し、template literal typeは文字列patternを型として合成します。強力な型計算はAPIの誤用を減らせますが、compile時間、error可読性、再帰深度を悪化させるため、型の目的と公開範囲を制限します。',
    (11, 'Decorator・Metadata・DI'): 'decoratorはclass、method、fieldなどの宣言へ追加処理を関連付けるmechanismで、proposal/TypeScript設定によってsemanticsが異なります。metadataは型やrouteなどの情報を宣言へ付与し、frameworkはreflectionで収集します。DI containerはprovider graphを構築してobject生成を代行し、singleton、request、transientなどのlifetimeと循環依存を管理します。',
    (11, 'Node.js Runtime'): 'Node.jsはJavaScript実行をV8、platform非依存の非同期I/Oとevent loopをlibuvへ依存します。network I/Oの多くはOSの readiness notificationを使い、file system、一部crypto/DNSなどはlibuv thread poolへ委譲されます。JavaScript callback自体は通常main threadで動くため、長いCPU処理、巨大JSON、同期API、microtaskの連鎖はevent loopを停止させます。',
    (11, 'Buffer・Stream・Backpressure'): 'BufferはNodeでbinary dataを扱うbyte列で、encoding変換と境界長を明示する必要があります。Readable/Writable streamはchunk単位で処理し、writeがfalseを返したらdrainまで待つことでproducerがconsumerを圧倒するのを防ぎます。pipelineはerror伝播とcloseをまとめ、highWaterMarkは速度そのものではなくbuffering量とbackpressure発生点を調整します。',
    (11, 'Module・Package・Toolchain'): 'CommonJSはrequire/module.exportsを実行時に評価し、ESMはimport/exportを静的に解析できるmodule systemです。package.jsonのtype、exports、imports、条件付きexportは利用可能なentryと公開面を決めます。transpile、type check、bundle、test、package publishを分離し、lockfileとworkspaceで依存解決を再現可能にします。',
    (11, 'Worker・Process・Native連携'): 'worker_threadsは同一process内に別V8 isolateを作ってCPU処理を並列化し、message passingまたはSharedArrayBufferで通信します。child_processはOS processとして強く隔離でき、clusterは複数processでportを共有する仕組みです。N-APIはABI安定なnative addon境界、WASMはportable sandboxed bytecodeですが、境界越しのcopyと細かな呼び出し回数が性能を相殺します。',
    (11, 'Node.js本番品質'): '本番Nodeではevent loop delay、CPU profile、heap snapshot、GC、active handle、thread-pool saturationを観測します。AsyncLocalStorageは非同期chainにrequest contextを伝播できますが、library境界や誤ったcallback連携を検証します。SIGTERMを受けたら新規受付を止め、in-flight requestとqueueを期限内に完了し、DB connectionやtelemetryをflushして終了します。',

    # 12 Go
    (12, 'Go言語基礎と設計哲学'): 'Goは小さな言語仕様、明示的error、composition、強い標準toolingにより、複数人で読みやすいserviceを作ることを重視します。zero valueが有効に使えるtypeは初期化負担を減らし、packageは公開APIを大文字名で明確にします。短さより依存方向とerror contextを優先し、interfaceは利用側で小さく定義します。',
    (12, '型・Interface・Generics'): 'Goのinterface実装は明示宣言不要で、method setが要求を満たせば代入できます。value receiverとpointer receiverではmethod setとmutation semanticsが異なります。genericsはtype parameterとconstraintでcompile-time再利用を可能にしますが、behaviorの抽象はinterface、container/algorithmの型再利用はgenericsという使い分けが基本です。',
    (12, 'メモリ・Pointer・Escape Analysis'): 'Go compilerは値の寿命を解析し、関数終了後も必要な値や安全にstackへ置けない値をheapへescapeさせます。pointerを使うだけで必ずheapになるわけではなく、closure capture、interface化、戻り値、sizeなどが影響します。benchmarkと-BCE/escape出力、pprof allocationを使い、推測でpointer化しないことが重要です。',
    (12, 'Goroutine・Channel'): 'goroutineはruntimeが多重化する軽量taskで、OS threadより小さく伸縮可能なstackを持ちます。unbuffered channelはsend/receiveの同期点、buffered channelは有限queueとして働きます。channelをcloseする責任、consumer停止時のproducer leak、selectの公平性、共有memoryの所有者を明確にします。',
    (12, 'Context・Cancellation・Timeout'): 'contextはrequest-scopedなdeadline、cancel signal、少量のmetadataをcall graphへ伝播します。parent cancelはchildへ伝わるため、作成したcancel functionを必ず呼び、database・HTTP client・goroutineがctx.Doneを監視するようにします。任意optionや大きなobjectをcontextへ入れると依存が見えなくなるため避けます。',
    (12, 'Go Runtime・Scheduler・GC'): 'Go schedulerのGはgoroutine、MはOS thread、Pは実行権とlocal run queueを表し、work stealingで負荷を分散します。syscallやnetwork pollerとの連携でMがblockしても別MがGを実行できます。GCはconcurrent mark-sweepを中心にpauseを抑えますが、allocation rate、pointer density、heap goalがCPUとlatencyへ影響します。',
    (12, '標準ライブラリで作るHTTP'): 'net/httpではHandlerがrequestからresponseを生成し、middlewareはHandlerを包む関数として構成できます。ServerにはReadHeaderTimeout、IdleTimeout、MaxHeaderBytes等を設定し、Clientは毎回作らずTransportとconnection poolを再利用します。response bodyを読み閉じ、context cancel、redirect、TLS、proxy、retryの責務を明確にします。',
    (12, 'Error・Testing・Tooling'): 'Go errorは通常値として返し、%wでcauseをwrapしてerrors.Is/Asで分類します。table-driven testは入力と期待を列で増やしやすく、subtestとparallel実行にはloop variableと共有fixtureへの注意が必要です。go test -race、go vet、fuzz、benchmark、pprofを標準の品質loopへ入れます。',
    (12, 'I/O・Serialization・Database'): 'io.Reader/Writerはstreaming I/Oの最小interfaceで、copy、buffer、compression、networkを合成できます。encoding/jsonは便利ですがreflectionとallocation、unknown field、number精度を確認します。database/sqlはconnection poolでありconnectionそのものではないため、MaxOpen/Idle/Lifetime、transaction context、row close、scan errorを管理します。',
    (12, 'Goサービスの本番運用'): 'Go binaryは静的配布しやすい一方、OS certificate、timezone、cgo、DNS resolverなど実行環境依存を確認します。graceful shutdownではsignal受信後にhealthを落とし、Server.Shutdownとbackground worker cancelを期限付きで行います。pprofとruntime metricsを保護されたendpointへ出し、race・leak・goroutine dumpを証拠に診断します。',

    # 13 Rust
    (13, 'Ownership・Move・Copy'): 'Rustでは各値に一つのownerがあり、ownerのscope終了時にDropで資源を解放します。assignmentや引数渡しは既定でmoveとなり、元変数からの利用をcompile時に禁止します。整数などCopy型はbitwise copyされますが、heap pointerやfile handleのような資源はmoveによりdouble freeを防ぎます。',
    (13, 'Borrow・Lifetime'): 'borrowは所有権を移さず参照を貸し、同時に複数のimmutable参照または一つのmutable参照というaliasing規則を守ります。lifetimeは参照が参照先より長生きしない関係を型へ表し、多くはelisionで推論されます。annotationは寿命を延ばす命令ではなく、複数参照間の関係をcompilerへ伝えるものです。',
    (13, 'Struct・Enum・Pattern Matching'): 'structは同時に存在するfieldの積型、enumは候補の一つだけが存在する和型です。OptionとResultに欠損・失敗を含め、matchのexhaustivenessで全状態を処理させます。boolean flagの組合せより状態ごとのvariantを使うと、不正な組合せを型で表現不能にできます。',
    (13, 'Trait・Generics・Dynamic Dispatch'): 'traitは共有behaviorを定義し、generic + trait boundは各具体型へmonomorphizeされるため静的dispatchと最適化が可能です。dyn Traitはvtableを使うdynamic dispatchで、異なる具体型を同じcollectionへ格納できます。associated typeは実装ごとに一つの関連型、generic parameterは利用ごとに選べる型という差があります。',
    (13, 'Error HandlingとAPI設計'): 'Result<T,E>は回復可能な失敗、panicは通常programmer errorや継続不能な不変条件違反に使います。? operatorはerrorをFrom変換しながら早期returnし、custom errorは原因とcontextを保ちます。library境界ではpanicを公開契約にしない、FFI/thread境界ではunwindを跨がせない、error分類をcallerの回復行動へ合わせることが重要です。',
    (13, 'Iterator・Closure・Zero-cost Abstraction'): 'Iterator adapterはlazyにchainされ、collectやfor等のconsumerで実行されます。compilerはgenericをmonomorphizeし、inlineやloop最適化によって高水準なchainを手書きloop相当にできます。allocation、closure capture、dynamic dispatch、bounds checkが残る場合はbenchmarkとIR/assemblyで確認します。',
    (13, 'ConcurrencyとSend・Sync'): 'Sendは値を別threadへ移して安全、Syncは共有参照を複数threadから使って安全であることを示すauto traitです。Arcはatomic reference countで共有ownerを作り、Mutex/RwLockが内部mutationを同期します。lock poisoning、critical section長、lock順、channel disconnect、thread panicの回復方針を決めます。',
    (13, 'Async Rust・Tokio'): 'Rust Futureはpollされるまで進まず、executorがwakeされたtaskを再pollします。awaitを跨ぐself-referenceの安全性にPinが関わり、Tokioはreactor、scheduler、timer、async I/Oを提供します。blocking処理をasync worker上で行わずspawn_blockingへ分離し、task leak、cancel safety、selectで途中まで進んだoperationを検証します。',
    (13, 'Unsafe・FFI・メモリ表現'): 'unsafeはcompilerが検証できない操作を許可しますが、aliasing、初期化、alignment、validity、lifetimeという安全条件を実装者が保証する必要があります。repr(C)でlayoutをC互換にし、raw pointerと長さ、ownership transfer、allocator、panic/error codeの契約をFFI境界に書きます。安全なpublic APIの内側へunsafeを小さく封じ、Miriやsanitizerで検証します。',
    (13, 'Cargo・Library・Production Rust'): 'Cargo workspaceは複数crateの依存とbuildを統合し、featureはoptional dependencyやcompile条件を制御します。public APIではsemver、MSRV、feature combination、Send/Sync、panic、unsafe contractを互換性として扱います。clippy、rustfmt、test、doctest、criterion、cargo-audit/deny、profile-guided設定をrelease pipelineへ組み込みます。',

    # 14 Backend / API
    (14, 'Webバックエンドの責務分解'): 'transport層はHTTPやRPCを解釈し、application層はuse caseの手順とtransaction境界を調整し、domain層は業務規則と不変条件を持ち、infrastructure層はDBや外部APIを実装します。すべてをcontroller/serviceへ詰めるとframework、永続化、業務判断が絡みます。依存方向を内側へ向け、境界ごとに入力・出力・失敗を明示します。',
    (14, 'REST API設計'): 'RESTfulなHTTP APIではresourceを名詞でmodel化し、methodの安全性・冪等性とstatus codeのsemanticsを守ります。createの重複防止にはidempotency key、更新競合にはETag/If-Match、一覧には安定sortとcursor paginationを使います。URL形だけでなくcacheability、conditional request、representation、error format、互換性が契約です。',
    (14, 'GraphQL・RPC・gRPC'): 'GraphQLはclientが必要fieldを選べるschema/query languageで、resolverのN+1、authorization、query complexityを制御します。RPCは操作中心で、gRPCはprotobuf contractとHTTP/2によりtyped unary/streaming通信を提供します。public Web、内部service、mobile、streamingなど、利用者と変更速度に応じて選びます。',
    (14, 'Express・Fastify・NestJS'): 'Expressは最小限のmiddleware/router model、Fastifyはschema-driven validation/serializationとhook/plugin encapsulation、NestJSはmodule・DI・decorator・request pipelineによる大規模構造を提供します。Nestも下層ではExpress/Fastify adapterへrequestを渡します。抽象化が増えるほどlifecycle、scope、metadata、error propagationを理解しないと性能・テスト・循環依存問題を見失います。',
    (14, 'Validation・Serialization・Error'): '外部inputは型注釈だけでは安全にならないため、runtime schemaで型、範囲、形式、unknown field、cross-field constraintを検証します。serializationは内部entityをそのまま返さず、公開DTOと権限に応じてfieldを制御します。errorはproblem details等の一貫形式にし、client向け情報と内部cause/stack/PIIを分離します。',
    (14, 'Authentication・Authorization'): 'authenticationは誰かを確認し、authorizationはその主体が対象へ何をできるかを判断します。session cookie、access/refresh token、OAuth/OIDCは脅威とclient種別に応じて選びます。RBACだけで足りない所有関係や属性条件はABAC/ReBAC/policyへ移し、controllerに散らさずpolicy enforcement pointを統一します。',
    (14, 'Transactionと整合性'): 'transactionは複数DB操作を一つの整合性単位にし、isolation levelが同時実行で見える現象を決めます。pessimistic lockは競合を先に止め、optimistic lockはversion差で検出します。DB commitとmessage送信を同一原子操作にできない場合、transactional outboxとidempotent consumerで最終的整合性を作ります。',
    (14, '非同期処理とジョブ'): 'queueはrequest処理から時間のかかる副作用を分離し、workerが後で実行します。at-least-once配信では同じjobが複数回届く前提でidempotencyとdeduplicationを設計します。retryは一時障害だけに限定し、exponential backoff、jitter、最大回数、DLQ、poison message、処理期限と観測を持たせます。',
    (14, 'API性能とスケーリング'): 'API性能はcontrollerの速度だけでなく、DB round trip、N+1、serialization、network、connection pool、queueingで決まります。cacheはcache key、TTL、invalidation、stampede、authorization境界を設計します。pagination、batching、compression、rate limitを適用し、p50だけでなくp95/p99とsaturationを負荷試験で確認します。',
    (14, '本番API運用'): 'API変更はserver deployより長くclientへ残るため、additive change、deprecation、consumer inventory、contract testでbackward compatibilityを保ちます。versioningは最後の手段で、feature negotiationやoptional fieldでも進化できます。dependency障害時にはtimeout、circuit breaker、fallback、partial responseを設計し、request IDとtraceで利用者影響を追跡します。',

    # 15 Architecture / DDD / Clean
    (15, '設計原則と品質属性'): '設計は見た目の綺麗さではなく、変更容易性、性能、可用性、セキュリティ、テスト性など品質属性の優先順位を実現する手段です。cohesionを高め、couplingを必要な契約へ限定し、情報隠蔽で変更理由をmodule内へ閉じます。SOLIDは目的ではなく、変更の軸と依存を整えるためのheuristicとして使います。',
    (15, 'モジュールと依存関係'): 'moduleは同じ理由で変わる知識を集め、外部には小さく安定したinterfaceだけを公開します。循環依存は責務境界が曖昧な信号で、shared abstraction、event、dependency inversion、module再分割で解きます。stable dependency principleにより、変化しやすい具体から安定したpolicyへ依存させます。',
    (15, 'DDD戦略設計'): 'DDDの戦略設計は巨大なdomainをbounded contextへ分け、各context内で用語とmodelの意味を一貫させます。core/supporting/generic subdomainを区別し、重要領域へ投資を集中します。context mapではupstream/downstream、customer-supplier、anti-corruption layerなどcontext間の関係と翻訳責任を明示します。',
    (15, 'DDD戦術設計'): 'entityはidentityで継続性を持ち、value objectは値と不変性で等価性を持ちます。aggregateはtransaction内で一貫性を守る境界で、外部はaggregate rootを通じて変更します。domain serviceはentity/value objectに自然に属さないdomain operation、repositoryはaggregate collectionのような永続化抽象です。',
    (15, 'Clean・Hexagonal・Onion'): 'これらのarchitectureは名称が違っても、business ruleをframework、DB、UI、外部serviceから独立させるdependency ruleを共有します。use caseはapplication固有の操作、portは内側が必要とするcontract、adapterはHTTP/DB等の具体実装です。layer数を増やすことではなく、変更理由とtest境界を分離することが目的です。',
    (15, 'Design Pattern'): 'patternは繰り返し現れる設計力学へ名前を与えます。Strategyはalgorithm差替え、Factoryは生成判断の隠蔽、Adapterはinterface変換、Observerはevent通知、Mediatorは多者間調整を中央化します。問題がない段階でpatternを先置きせず、変化軸と依存を確認して最小構造を選びます。',
    (15, 'CQRS・Event-driven Design'): 'CQRSはcommandによる状態変更とqueryによる読み取りをmodel・責務として分離します。domain eventは完了した事実を表し、projectionはeventから読取modelを構築します。分離はscaleや複雑なworkflowに有効ですが、eventual consistency、重複、順序、schema evolution、debugging costが増えるため適用範囲を限定します。',
    (15, 'モノリス・モジュラーモノリス・Microservices'): 'monolithは一つのdeployableでtransactionとdebugが単純、modular monolithはdeployを保ちながら内部境界を強化します。microservicesは独立deployとteam ownershipを得る代わりにnetwork、分散data、observability、契約、運用のcostを負います。組織とdomain境界が未成熟な段階でprocessだけ分けるとdistributed monolithになります。',
    (15, 'Architecture DecisionとEvolution'): 'ADRはcontext、decision、代替案、結果を短く残し、後から「なぜ」を復元できるようにします。architecture fitness functionは依存、latency、securityなど重要特性を自動検証します。legacy移行ではstrangler patternやexpand-contractを使い、big bangではなく可逆な段階へ分け、再評価triggerを定義します。',
    (15, '設計レビューと可視化'): 'C4 modelはsystem context、container、component、codeへ段階的にzoomし、sequence diagramは時間順の相互作用を示します。図は箱の美しさではなく、責任、data ownership、trust boundary、同期/非同期、failure pathをレビュー可能にするものです。reviewでは要件、前提、trade-off、未解決risk、観測とrollbackを確認します。',

    # 18 AWS / Cloud
    (18, 'Cloud設計原則と責任共有'): 'cloud providerは物理facility、hardware、managed service基盤を守り、利用者はidentity、data、network設定、OSやapplicationなど利用層に応じた責任を持ちます。Regionは地理的範囲、AZは独立障害domainです。可用性、セキュリティ、性能、コスト、運用、持続可能性を同時に検討し、managed化で消える作業と残る責任を分けます。',
    (18, 'AWS Network'): 'VPCは論理的に隔離されたnetworkで、subnetはAZ内のIP range、route tableが宛先ごとのnext hopを決めます。Security Groupはstatefulなresource firewall、NACLはsubnet境界のstateless ruleです。Internet/NAT Gateway、VPC endpoint、PrivateLink、Transit Gatewayを使い、public/privateという名前ではなく実際のrouteとpublic IP、policyで到達性を判断します。',
    (18, 'Compute'): 'EC2はOSまで制御でき、Auto Scalingでcapacityを調整します。Lambdaはeventごとの短時間実行と運用削減、ECS/Fargateはcontainer単位の長時間serviceとjobに向きます。起動時間、runtime制約、connection、state、network、observability、単価、team能力を比較し、単純な「serverlessかserverか」で決めません。',
    (18, 'Storage・CDN'): 'S3はobject storageで高い耐久性、EBSはEC2へattachするblock、EFSは複数clientからmountできるfile storageです。CloudFrontはedge cacheとTLS終端で配信距離とorigin負荷を減らします。object key、versioning、lifecycle、encryption、cache key、signed access、replication、delete保護をdata lifecycleに合わせます。',
    (18, 'Managed Database'): 'RDS/Auroraはrelational transaction、DynamoDBはpartition key中心の低latency key-value/document、ElastiCacheはmemory上のcache/coordination、OpenSearchは全文・分析検索に使います。service名から選ばず、access pattern、整合性、query、size、growth、backup、復旧、connection、運用skillを先に定義します。',
    (18, 'IAM・Organizations・Governance'): 'IAM policyはprincipalがどのactionをどのresourceへ、どのconditionで行えるかを評価します。roleとSTSの一時credentialを使い、long-lived access keyを減らします。Organizations/SCPはaccount内principalへ権限を付与するのではなく最大権限のguardrailを設定し、multi-accountで環境・workload・security責任を分離します。',
    (18, 'Load Balancing・API・Event'): 'ALBはHTTP-awareなL7 routing、NLBは高性能なL4 connection、API GatewayはAPI公開、認証、throttle、変換をmanaged化します。SQSはqueue、SNSはfan-out通知、EventBridgeはevent bus/rule routingです。同期request、非同期command、domain eventを分け、retry、ordering、DLQ、idempotencyを設計します。',
    (18, 'Observability・Security'): 'CloudWatchはmetrics/logs/alarms、CloudTrailはAPI監査、Configはresource設定と履歴、GuardDutyは複数signalから脅威を検出します。KMSはdata keyを保護するkey managementを提供します。logを集めるだけでなく、account/region横断の保管、改ざん耐性、retention、alert owner、incident runbookまで設計します。',
    (18, 'Infrastructure as Code'): 'IaCはresourceを宣言し、review、再現、差分、rollback可能にします。CloudFormation/CDKはAWS native、Terraformはproviderとstateで複数platformを扱います。logical ID/resource replacement、state lock、secret、module version、drift、manual change、import、destroy protectionを運用規約へ含めます。',
    (18, 'Cost・Reliability・Disaster Recovery'): 'cloud costは使用量×単価だけでなく、data transfer、idle capacity、log retention、NAT、license、運用時間を含みます。RTOは復旧までの許容時間、RPOは失ってよいdata時間です。multi-AZ、backup/restore、warm standby、active-activeを段階化し、復旧手順を実際にtestして初めてDR能力になります。',

    # 21 SRE
    (21, 'ReliabilityとSRE原則'): 'SREは運用問題を人手で吸収するのではなく、software engineeringで信頼性とscaleを管理します。信頼性は100%を目指す絶対値ではなく、ユーザーjourneyと事業riskに対する適正水準です。toilを計測し、繰り返し・手作業・自動化可能・長期価値の低い作業を減らします。',
    (21, 'SLI・SLO・SLA'): 'SLIは実測するsignal、SLOは目標範囲、SLAは外部契約と違反時の責任です。availabilityだけでなくlatency、freshness、correctness、durabilityをuser-visible eventの比率として定義します。error budgetは許容失敗量であり、信頼性改善とfeature速度を同じ単位で意思決定する仕組みです。',
    (21, '監視とAlerting'): 'pageは人が今行動すべきuser symptomに限定し、原因候補や低優先情報はticket/dashboardへ分けます。burn-rate alertはerror budgetの消費速度を短期・長期windowで検出し、単一thresholdより急性・慢性の両方を捉えます。各alertにowner、impact、first action、silence条件、runbook、検証方法を持たせます。',
    (21, 'Incident Response'): 'incidentではseverityと役割を早期に定め、incident commander、operations、communication、scribeを分離します。最初の目的は根本原因の証明ではなくimpact縮小で、rollback、traffic shift、feature disableなど可逆なmitigationを優先します。timeline、decision、evidence、customer communicationを一つのchannelへ集約します。',
    (21, 'Postmortem・学習文化'): 'blameless postmortemは責任を曖昧にするのではなく、当時の情報と合理性を理解し、systemが人を失敗へ導いた条件を探します。root cause一つで終わらず、trigger、contributing factor、detection gap、recovery frictionを整理します。action itemはowner、期限、検証可能な完了条件、risk reductionを持たせます。',
    (21, 'Capacity Planning'): 'capacity planningはtraffic予測、service demand、resource utilization、saturation point、headroomを結びます。平均QPSだけでなくpeak、seasonality、request mix、data growth、dependency limitをmodel化します。load shedding、queue、priority、admission controlで過負荷時に重要機能を守ります。',
    (21, 'Resilience Pattern'): 'timeoutは無限待ちを防ぎ、retryは一時障害の成功率を上げますが、無制限retryは負荷を増幅します。circuit breakerは失敗中dependencyへの呼び出しを一時停止し、bulkheadはresource poolを分離して連鎖障害を防ぎます。budget、deadline、idempotency、jitter、fallback品質をend-to-endで設計します。',
    (21, 'Disaster Recovery'): 'backupは存在だけでなくrestore可能性が価値です。data、configuration、secret、artifact、DNS、identity、運用手順を復旧対象としてinventory化します。定期restore testとfailover exerciseでRTO/RPOを測り、primary障害時にcontrol planeや人のaccessまで使えるか確認します。',
    (21, 'Chaos Engineering'): 'chaos engineeringは無作為に壊すことではなく、steady state metricと仮説を定め、限定されたblast radiusでfailureを注入する実験です。最初はdependency latency、instance loss、packet loss、credential expiryなど既知riskから始めます。abort condition、observer、rollback、学習内容を事前に決めます。',
    (21, 'SRE組織と運用自動化'): 'on-callはservice ownershipと改善feedbackを結ぶ仕組みで、過剰pageや知識集中を放置すると持続不能になります。runbookで初動を標準化し、頻出かつ判断が明確な手順をautomationへ移します。production readiness reviewではSLO、capacity、dependency、security、backup、deploy/rollback、observability、ownerを確認します。',

    # 24 Security
    (24, 'Security MindsetとThreat Modeling'): 'threat modelingは守るasset、actor、entry point、trust boundary、abuse caseを設計段階で可視化します。STRIDE等は漏れを減らす分類であって、checklist完了が安全を保証するものではありません。riskはlikelihoodとimpactだけでなく、検知可能性、blast radius、回復性、攻撃者costも含めて優先します。',
    (24, 'Identity・Authentication'): 'passwordはsalt付きの適切なpassword hashingで保存し、MFAで単一credential漏えいへ備えます。session IDやtokenは推測不能、短命、rotation/revocation可能にし、browserではSecure、HttpOnly、SameSite cookieを使います。OAuthはauthorization delegation、OIDCはidentity layerであり、redirect URI、state、nonce、PKCE、issuer/audience検証が重要です。',
    (24, 'Authorization'): 'RBACはroleへpermissionをまとめ、ABACはsubject/resource/environment属性、ReBACは所有・所属などrelationshipで判断します。policy decisionとenforcementを分け、default deny、least privilege、tenant境界、object-level authorizationを全endpointで一貫させます。UIでbuttonを隠すことはauthorizationではなく、server側のresourceごとの検査が必要です。',
    (24, 'Web Application Security'): 'XSSは未信頼dataがcodeとしてbrowserで実行される問題で、context-aware escaping、safe DOM API、CSPで防ぎます。CSRFはbrowserがcredentialを自動送信する性質を悪用し、SameSite、CSRF token、origin確認を使います。SQL injectionはparameterized query、SSRFはallowlist、URL解析、network egress制限、metadata保護で対処します。',
    (24, 'API・Service Security'): 'APIはschema validation、authentication、object-level authorization、rate/size limit、idempotency、auditを境界で実施します。JWTはsignatureだけでなくalgorithm、issuer、audience、expiry、key rotationを検証します。service間はworkload identityとmTLS等で主体を確認し、shared static secretやnetwork内だから信頼する設計を避けます。',
    (24, 'Network・Cloud Security'): 'segmentationは侵入を完全に防ぐのではなく、到達可能範囲とblast radiusを減らします。zero trustはlocationだけで信頼せず、主体、device、context、resourceごとに継続検証する考え方です。cloudではIAM、security group、private endpoint、encryption、logging、organization guardrailをcodeとpolicyで標準化します。',
    (24, 'Cryptography基礎'): 'symmetric encryptionは同じ秘密鍵で高速に暗号化し、asymmetric cryptographyはpublic/private keyでkey exchangeやsignatureを実現します。hashは一方向要約、MACは共有鍵による完全性・真正性、digital signatureはprivate key署名とpublic key検証です。独自暗号を作らず、nonce再利用、mode選択、key rotation、randomness、key storageをlibrary契約通りに扱います。',
    (24, 'Secure SDLC・Supply Chain'): 'secure SDLCはrequirement、design review、threat model、code review、SAST/DAST、dependency scan、penetration test、incident feedbackを開発loopへ組み込みます。secret scanningと短命credentialで漏えいimpactを下げ、SBOM、署名、attestation、pinned dependencyでbuildから配布までのprovenanceを確認します。',
    (24, 'Privacy Engineering'): 'privacy engineeringは収集前に目的、必要性、保持期間、利用者権利を定め、data minimizationとpurpose limitationを実装します。pseudonymizationは対応表があれば再識別可能、anonymizationは現実には外部dataとの結合riskを評価する必要があります。access、export、delete、retention、consent、auditをdata lineageへ結びます。',
    (24, 'Incident・Forensics・Security Operations'): 'security incidentでは検知、triage、containment、eradication、recoveryを進めつつ、証拠の完全性とchain of custodyを保ちます。credential revoke、network isolation、snapshot、log保全の順序を事前にrunbook化します。攻撃経路だけでなく、dwell time、権限拡大、data access、persistence、検知gapをtimelineで再構成します。',

    # 25 QA
    (25, 'Quality ModelとTest Strategy'): '品質は「バグがない」だけでなく、機能適合、信頼性、性能、セキュリティ、使いやすさ、保守性など複数属性です。test strategyはsystem riskとfeedback speedから、unit、integration、E2E、static、exploratory、production monitoringを配分します。test pyramidは件数の宗教ではなく、速く局所化できる検証を厚くする原則です。',
    (25, 'Unit Testing'): 'unit testは小さなbehaviorを高速・決定的に検証し、失敗箇所を局所化します。test doubleは境界の観測や制御に使いますが、内部呼び出し手順を過度にmockするとrefactorで壊れます。入力境界、不変条件、error、状態遷移を対象にし、clock/randomness/I/Oを制御可能な依存へします。',
    (25, 'Integration・E2E Testing'): 'integration testはDB、queue、frameworkなど実境界の契約を確認し、E2Eは利用者journeyを入口から出口まで検証します。containerやephemeral environmentで実依存を使い、migration、encoding、transaction、network、authの差を捕捉します。件数を絞り、fixture isolation、並列実行、診断artifactを整えます。',
    (25, 'Contract Testing'): 'contract testはproviderとconsumerのrequest/response/message期待を独立に検証し、統合環境へ集める前に破壊的変更を検出します。consumer-driven contractは実利用を表せますが、全体business semanticsや非機能を保証しません。schema registry、compatibility rule、version、deprecation、mock driftを管理します。',
    (25, 'Property-based・Metamorphic Testing'): 'property-based testingは個別例ではなく、generatorで多数inputを作り不変条件を検証し、失敗時はshrinkingで最小反例を探します。正解oracleを作りにくい場合、入力変換に対する出力関係を使うmetamorphic testingが有効です。generatorが現実の重要領域を覆うか、preconditionで失敗を隠していないかを確認します。',
    (25, 'Fuzzing・Security Testing'): 'fuzzingは構造化・非構造化inputを大量生成し、crash、hang、sanitizer違反、invariant破壊を探します。coverage-guided fuzzerは新しいcode pathへ到達するinputをcorpusへ残します。parser、protocol、file format、FFI境界へ適用し、発見inputをregression testとして固定します。',
    (25, 'Mutation・Static Analysis'): 'mutation testingはoperator変更や条件反転など人工的な欠陥を入れ、testが検出できるかを測ります。高coverageでもmutationが生き残ればassertionが弱い可能性があります。static analysisは実行せずAST/CFG/data-flow/typeを解析し、ruleごとのfalse positive、severity、autofix、安全なbaseline運用を設計します。',
    (25, 'Performance・Reliability Testing'): 'load testは想定負荷、stressは限界超過、spikeは急増、soakは長時間劣化を確認します。単にQPSを出すのではなく、現実的なrequest mix、data size、think time、cache warmness、dependencyを再現します。fault injectionとrestore testを組み合わせ、SLO、degradation、recovery timeを検証します。',
    (25, 'Test Data・Environment・Flakiness'): 'flaky testはtime、random、order、shared state、network、resource contention、eventual consistencyなど未制御要因で結果が変わります。retryで隠さず、seed、fake clock、unique data、transaction cleanup、wait条件、resource quotaを整えます。production dataを使う場合はprivacy、masking、representativeness、再現性を管理します。',
    (25, 'QA ProcessとRelease Decision'): 'release判断はpass/failの件数ではなく、変更範囲、risk、未検証領域、defect severity、observability、rollback可能性を統合します。exploratory testingはcharterとtimeboxを持ち、testerの学習に応じて次の探索を変えます。quality gateは硬直したcoverage値ではなく、重大riskに対する証拠を要求する仕組みにします。',

    # 27 ML
    (27, 'ML問題設定'): 'MLでは最初にprediction対象、decision、loss、利用時点で得られるfeature、label生成方法を定義します。train/validation/testを時間・主体・groupで適切に分離し、未来情報やtarget由来情報が混ざるdata leakageを防ぎます。高度modelより、単純baselineと非ML解法を比較し、予測が事業行動を改善するか確認します。',
    (27, '回帰・分類'): 'linear regressionはfeatureの線形結合で連続値を予測し、logistic regressionはlog-oddsを線形model化して確率を出します。lossを最小化し、L1/L2 regularizationで複雑性を抑えます。feature scaling、multicollinearity、class imbalance、threshold、calibrationを扱い、係数の解釈条件を確認します。',
    (27, 'Tree・Ensemble'): 'decision treeはfeature thresholdで空間を再帰分割し、非線形とinteractionを扱えます。random forestはbootstrapとfeature samplingでvarianceを下げ、gradient boostingは前modelのerrorを順次補正します。depth、leaf size、learning rate、tree数をvalidationし、feature importanceのbiasや相関を解釈時に考慮します。',
    (27, 'Unsupervised Learning'): 'clusteringは類似度に基づくgroup、dimensionality reductionは情報を保ちながら低次元表現、anomaly detectionは通常分布からの逸脱を探します。正解labelがないため、metricだけでなく安定性、業務意味、downstream utilityを評価します。distance、scaling、density仮定が結果を大きく変えます。',
    (27, '評価と実験'): 'precisionは陽性予測の正しさ、recallは実陽性の捕捉率で、失敗costに応じてthresholdを選びます。ROC-AUCはrank能力、PR-AUCはrare positiveで有用、calibrationは予測確率と実頻度の一致です。cross validation、confidence interval、slice別error analysis、baseline比較で偶然と偏りを減らします。',
    (27, 'Neural Network基礎'): 'neural networkは線形変換と非線形activationを層状に合成し、backpropagationでchain ruleを使ってloss gradientを計算します。optimizerがparameterを更新し、initialization、normalization、learning rate、batch sizeが学習安定性へ影響します。train loss低下だけでなくvalidation、gradient、activation、overfitを監視します。',
    (27, 'CNN・Sequence Model'): 'CNNは局所receptive fieldとweight sharingで画像等の空間patternを抽出します。RNN/LSTMは時系列状態を再帰的に更新しますが、長距離依存と逐次計算に課題があります。attentionは各位置から他位置への関連を重み付き集約し、sequenceをより並列に処理できます。',
    (27, 'Transformer'): 'Transformerはquery-key similarityでattention weightを作り、valueを加重集約します。multi-head attentionは異なる関係を並列に学び、position情報を別途加えて順序を表します。residual、normalization、feed-forward、maskが安定学習とdecoderのcausal制約を支え、計算・memoryはsequence lengthに強く依存します。',
    (27, 'Generalization・Robustness'): 'biasはmodelが単純すぎる誤差、varianceはdata変化へ過敏な誤差で、regularizationとdata量・質で均衡を取ります。本番ではcovariate/label/concept shiftが起き、offline scoreが維持されません。slice、stress、out-of-distribution、adversarial、uncertaintyを評価し、人へのfallbackを設計します。',
    (27, 'Responsible ML'): 'fairnessはgroup間metricを一つ揃えるだけではなく、利用文脈、historical bias、base rate、harmを考慮します。explainabilityはmodel内部説明と個別decision説明を区別し、誤った確信を与えないようにします。privacy、consent、human oversight、appeal、monitoring、decommissionまでmodel lifecycleへ含めます。',

    # 28 LLM
    (28, 'LLM全体像'): 'LLMは大規模textから次token予測を学び、言語pattern、知識、task behaviorをparameterへ圧縮したfoundation modelです。pretraining後にinstruction tuningやpreference optimizationを行い、inference時はcontextに条件付けてtokenを生成します。流暢さは真実性を保証せず、context限界、hallucination、非決定性、知識時点、tool権限をsystem側で補います。',
    (28, 'Tokenization・Embedding'): 'tokenizerはtextをsubword等のID列へ変え、同じ文字数でも言語や記号でtoken数が変わります。embeddingはitemをvectorへ写し、近さを意味類似のproxyとして使いますが、taskに不要な相関やdomain shiftを含みます。chunk boundary、normalization、distance metric、index、recallをend-to-end taskで評価します。',
    (28, 'Transformer内部'): 'self-attentionは各tokenのqueryと他tokenのkeyの類似度からvalueを集約します。KV cacheは過去tokenのkey/valueを再利用してautoregressive decodeを高速化しますが、context lengthとbatchに比例してmemoryを消費します。normalization、residual、feed-forward、attention implementation、quantizationが品質・速度・数値安定性へ影響します。',
    (28, 'Pretraining・Scaling・Data'): 'pretrainingは大量corpus上のnext-token objectiveを最適化し、data mixture、deduplication、quality、domain比率が能力とbiasを決めます。model/data/computeを増やすと一定範囲でlossが予測可能に下がりますが、能力や安全性が一様に伸びるわけではありません。benchmark contaminationとmemorizationを避け、held-out評価を設計します。',
    (28, 'Post-training・Alignment'): 'SFTは望ましいinput-output例でbehaviorを教え、preference optimizationは複数responseの比較から好ましい応答を強めます。RLHFはreward modelと強化学習を使う代表方式ですが、直接選好最適化など別手法もあります。helpfulness、安全性、style、reasoning、over-refusal、reward hackingのtrade-offを評価します。',
    (28, 'Prompt・Context Engineering'): 'promptはtask、制約、利用可能data、出力schema、例、失敗時behaviorを明示します。structured outputはparserとschema validationを組み合わせ、文章上の依頼だけに依存しません。長いcontextは情報量を増やす一方、重要情報の埋没、矛盾、cost、latencyを増やすため、retrieval、summary、ranking、context compressionを使います。',
    (28, 'RAG・Memory'): 'RAGはqueryから外部sourceをretrieveし、選んだevidenceをcontextへ渡して生成をgroundします。chunking、metadata filter、hybrid retrieval、reranking、citation mappingがanswer品質を決めます。memoryは会話中のstate、user preference、長期事実、episodic recordを分け、保存同意、更新、矛盾、削除、source provenanceを管理します。',
    (28, 'Agent・Tool Use'): 'agentはmodelがstateを見て次のaction/toolを選び、結果を取り込むloopです。自由な長期planningより、state machine、bounded step、typed tool、permission、budget、checkpointで失敗範囲を制御します。tool outputを未信頼inputとして扱い、prompt injection、side effect confirmation、idempotency、compensation、human approvalを設計します。',
    (28, 'LLM Evaluation'): 'LLM評価はtask dataset、rubric、deterministic checker、人評価、model judgeを組み合わせます。LLM-as-judgeにはposition/style/self-biasがあるため、blind化、複数judge、校正、人手sampleを使います。平均scoreだけでなくfailure taxonomy、slice、variance、cost、latency、安全性、online outcomeを継続追跡します。',
    (28, 'LLM Security・Safety・Economics'): 'prompt injectionは外部contentがsystem instructionを上書きしようとする問題で、instruction/data分離、tool permission、output validation、sandbox、human approvalが必要です。guardrail一層で完全防御せず、input・model・tool・data・outputの多層防御にします。token、cache、batch、model routing、retry、context、GPU占有を測り、品質当たりcostとtail latencyを最適化します。',
}


MODULE_PRIMERS.update({
    # 01 Mathematics / Statistics
    (1, '離散数学と論理'): '集合は対象の集まり、写像は各入力へ出力を対応させる規則、関係は要素間の組を表します。命題論理は真偽を持つ文、述語論理は変数と量化を含む性質を扱います。帰納法は基底と帰納stepにより無限個のcaseを証明し、再帰的data構造やalgorithmの正しさへ直結します。',
    (1, '組合せ論と数え上げ'): '順列は順序を区別する配置、組合せは選択集合を数えます。包除原理は重複して数えた領域を交互に補正し、鳩の巣原理は対象数が箱数を超えれば衝突が必ず起きることを示します。生成関数は数列を形式的power seriesへ写し、再帰式や数え上げを代数操作へ変換します。',
    (1, '確率の基礎'): '標本空間は起こり得る結果全体、事象はその部分集合です。条件付き確率は別事象が起きた情報で確率を更新し、Bayesの定理は事前確率と尤度から事後確率を計算します。独立性は同時確率が積へ分解できる強い条件で、無相関とは同じではありません。',
    (1, '確率分布'): '確率分布はrandom variableが各値を取る規則を表し、期待値は長期平均、分散は散らばりです。Bernoulli/二項は独立な成功回数、Poissonは一定rateの稀なevent数、正規分布は多くの小さな独立要因の和を近似します。平均と分散が同じでもtailや歪度は異なるため、分布形を確認します。',
    (1, '統計的推定'): '標本から母集団parameterを推定する際、点推定は一つの値、区間推定は不確実性を含む範囲を返します。最尤推定は観測dataが最も起こりやすくなるparameterを選びます。biasとvarianceは推定器の系統誤差とdata変動への感度で、sample sizeとmodel assumptionに依存します。',
    (1, '仮説検定と実験'): '仮説検定は帰無仮説の下で観測以上に極端なdataが出る確率をp値として計算し、事前に決めた有意水準と比較します。p値は仮説が正しい確率でも効果量でもありません。検出力、sample size、multiple testing、停止規則、実務上の効果量を合わせてA/B testを解釈します。',
    (1, '線形代数'): 'vectorは方向と量、matrixは線形変換や連立方程式を表します。固有vectorは変換で方向が変わらずscaleだけ変化する軸で、固有値が倍率です。SVDは任意matrixを回転・scale・回転へ分解し、低rank近似、次元削減、least squares、condition解析へ使われます。',
    (1, '微積分と最適化'): '微分は入力の微小変化に対する出力変化率、gradientは多変数関数の最急上昇方向です。chain ruleは合成関数の微分を局所微分の積へ分解し、backpropagationの基礎になります。制約付き最適化ではLagrange multiplier等を使い、局所解、convexity、step size、conditioningを確認します。',
    (1, '情報理論'): 'entropyは確率分布の平均的な不確実性、相互情報量は一方の観測で他方の不確実性がどれだけ減るかを表します。KL divergenceは二分布のずれを非対称に測り、cross entropyやvariational inferenceへ現れます。source coding theoremは平均code長の限界をentropyへ結び、圧縮と予測を同じ視点で理解できます。',
    (1, '時系列と意思決定'): '時系列では隣接時点が独立でないため、trend、seasonality、自己相関を分離します。移動平均はnoiseを平滑化しますが遅延を生み、未来情報を混ぜるとleakageになります。Bayes意思決定は各actionの期待損失を比較し、Monte Carlo法は複雑な期待値をrandom sampleで近似します。',

    # 02 Algorithms
    (2, '計算量と漸近解析'): 'Big Oは十分大きな入力での上界、Omegaは下界、Thetaは同じorderの上下界を表します。最悪・平均caseに加え、動的配列の拡張のように一連の操作全体でcostを割る償却解析があります。実測ではconstant、cache、I/O、distributionが効くため、理論orderとbenchmarkを両方使います。',
    (2, '配列・連結リスト・スタック・キュー'): '配列は連続memoryに置かれrandom accessとcache localityが良い一方、途中挿入は移動を伴います。連結listはnodeをpointerで繋ぎ局所挿入を容易にしますが、探索とcache効率が弱くなります。stackはLIFO、queueはFIFOで、ring bufferは固定配列上でhead/tailを循環させます。',
    (2, 'ハッシュテーブル'): 'hash tableはkeyをhash値からbucketへ写し、平均的にO(1)の検索を実現します。collisionはchainingやopen addressingで解決し、load factorが高いとprobeやchainが伸びます。hash floodへの耐性、iteration order、resize pause、一貫性hashによるnode増減時の再配置量を確認します。',
    (2, '木構造'): '二分探索木は左<root<右の順序で検索しますが、偏るとlist同様になります。AVLやRed-Black treeは回転で高さをO(log n)に保ちます。B/B+treeは一nodeに多数keyを持ってdisk page I/Oを減らし、Trieは文字prefixをedgeとして共有します。',
    (2, 'ヒープと優先度付きキュー'): 'binary heapは完全二分木を配列で表し、親子の優先関係を保ってmin/max取得をO(1)、挿入・削除をO(log n)で行います。heapifyはbottom-upならO(n)です。scheduler、Dijkstra、Top-K、streaming medianでは、必要操作とmemory量に応じて複数heapやbounded heapを使います。',
    (2, 'ソートと選択'): '比較sortにはOmega(n log n)の下界があり、merge sortは安定かつworst O(n log n)、quick sortは平均高速でin-placeですがpivot次第で劣化します。counting/radixはkey範囲や桁を利用して比較下界を避けます。安定性、memory、既ソート度、外部sort、parallel性を入力特性から選びます。',
    (2, 'グラフアルゴリズム'): 'BFSは辺数基準の最短距離、DFSは到達・cycle・component探索に使います。Dijkstraは非負weight、Bellman-Fordは負辺、Floyd-Warshallは全点対へ適します。Kruskal/Primは最小全域木、topological sortはDAGの依存順を作り、graph表現の隣接list/matrixが計算量を変えます。',
    (2, '動的計画法と貪欲法'): 'dynamic programmingは重複部分問題の結果を保存し、最適部分構造をstate transitionで解きます。stateの意味、遷移、初期値、計算順、復元方法を明示すると設計できます。greedyは各stepの局所最善が全体最善になる証明が必要で、交換argumentやmatroid性が根拠になります。',
    (2, '文字列アルゴリズム'): 'KMPはpatternのprefix/suffix情報で照合位置を戻さずO(n+m)、Rabin-Karpはrolling hashで候補を絞ります。suffix array/treeは全suffixを索引化して部分文字列検索を高速化します。編集距離は挿入・削除・置換の最小回数をDPで求め、Unicode normalizationとcode point/grapheme境界を実装で確認します。',
    (2, '高度なアルゴリズム設計'): '分割統治は問題を独立な小問題へ分け、結果を結合します。randomized algorithmは入力や選択へrandomnessを入れて期待性能や単純性を得ます。近似algorithmは最適値との比を保証し、online algorithmは未来入力を知らず逐次判断するためcompetitive ratio等で評価します。',

    # 03 Computation Theory
    (3, '形式言語とオートマトン'): '形式言語はalphabet上のstring集合で、regular languageは有限状態automatonで認識できます。NFAとDFAは表現力が同じで、subset constructionで変換できます。正規表現は実装にbacktracking拡張がある場合があるため、理論上のregular expressionと性能特性を区別します。',
    (3, '文脈自由文法'): 'context-free grammarはnonterminalを書き換えて入れ子構造を生成し、pushdown automatonのstackで認識できます。parse treeは生成規則の適用構造を表し、同じstringに複数treeがあるとgrammarは曖昧です。左再帰、優先順位、結合規則を調整してprogramming languageのsyntaxを定義します。',
    (3, 'チューリング機械'): 'Turing machineは有限制御、読み書きhead、無限tapeからなる抽象machineで、algorithmically計算可能な関数の標準modelです。universal machineは別machineの記述をinputとしてsimulationできます。停止問題は任意programが停止するかを一般に判定するalgorithmが存在しないことを対角化で示します。',
    (3, '決定可能性と帰着'): 'decision problemはyes/noを返す問題で、常に停止するmachineがあればdecidableです。mapping reductionは問題AのinstanceをBへ変換し、Bを解ければAも解けることを示します。既知のundecidable問題から新問題へ帰着することで、不可能性や解析toolの限界を証明できます。',
    (3, '計算量クラス'): 'Pはdeterministic polynomial time、NPは解のcertificateをpolynomial timeで検証できる問題群です。co-NPはno側certificate、PSPACEはpolynomial spaceで解ける問題です。class包含関係とcomplete問題を理解し、実務の「難しい」を入力size、parameter、approximation可能性へ分解します。',
    (3, 'NP完全性'): 'NP-complete問題はNPに属し、すべてのNP問題からpolynomial reductionされる最難関群です。Cook-Levin theoremはSATがNP-completeであることを示し、3-SAT、Clique、Vertex Cover、Hamiltonian path等へ連鎖的に帰着できます。新問題ではdecision版を定義し、NP membershipとhardnessを別々に示します。',
    (3, '近似可能性'): 'approximation ratioはalgorithm解と最適解の距離をworst caseで保証します。PTASは任意epsilonに対してpolynomial timeの近似scheme、FPTASは1/epsilonにもpolynomialです。gap reductionやPCP的結果により一定比以上の近似が困難な問題もあり、heuristicの実測と理論保証を区別します。',
    (3, 'パラメータ化計算量'): 'parameterized complexityは入力size nだけでなく、解size kやtreewidth等を分離してO(f(k) n^c)ならFPTと呼びます。kernelizationはpolynomial時間で同値な小instanceへ縮約します。実務では全体規模が大きくても難しい構造parameterが小さい場合、正確解が現実的になります。',
    (3, '確率的計算'): 'Monte Carlo algorithmは時間を固定し小確率で誤り、Las Vegas algorithmは常に正しいが実行時間がrandomです。error probabilityは独立反復で指数的に下げられます。BPPはbounded-error probabilistic polynomial timeで、random bit品質、adversarial input、再現seedを実装上扱います。',
    (3, '量子計算の理論基礎'): 'qubitは複素amplitudeの重ね合わせを持ち、unitary gateで状態を変換しmeasurementで確率的にbitを得ます。entanglementとinterferenceを利用するquantum circuitは、ShorやGrover等の特定問題でspeedupを示します。BQPは量子polynomial timeのclassですが、すべてのNP問題を高速化する証拠はありません。',

    # 04 Formal Methods
    (4, '命題論理と述語論理'): '論理のsyntaxは式の形、semanticsはmodelでの真偽を定めます。自然演繹やsequent calculusは推論規則に従い証明を構築し、soundnessは証明可能なら真、completenessは真なら証明可能という関係です。SAT/SMT solverは充足可能性を機械的に探索し、仕様矛盾や反例を見つけます。',
    (4, '集合・関係・代数的仕様'): '関係はstate間の対応やoperationを集合として表せ、同値関係は反射・対称・推移、順序は比較可能性を形式化します。代数的仕様はdata typeをconstructorとequationで定義します。実装詳細を捨て、観測可能なoperationとlawだけを記述すると複数実装を同じcontractで検証できます。',
    (4, '状態機械'): '状態機械は現在stateとevent/inputから次stateとoutputを決めます。transition guardとactionを明示し、到達不能state、nondeterminism、invalid transitionを検査します。invariantは全到達stateで保つ性質、state explosionは並行componentの直積で状態数が急増する問題です。',
    (4, '時相論理'): 'LTLは一本の実行path上でalways、eventually、until等を表し、CTLは分岐する未来pathへ量化します。safetyは悪いことが起きない、livenessは良いことがいつか起きる性質です。自然言語の「常に」「最終的に」「応答するまで」を時相式へ変換し、fairness条件を明示します。',
    (4, 'モデル検査'): 'model checkerは有限state modelを網羅探索し、property違反なら具体的counterexample traceを返します。BDDやSAT/SMT、partial-order reduction、symmetry、abstractionでstate explosionを抑えます。実装全体を忠実再現せず、正しさに必要なstateとtransitionだけを抽象化する能力が重要です。',
    (4, '定理証明'): 'interactive theorem proverでは型付きlogic内でdefinition、lemma、proofを構築し、kernelが小さなproof objectを検査します。induction、case split、rewrite、automationを組み合わせます。仕様そのものが誤っていれば正しいproofでも価値がないため、executable exampleとmodel reviewを併用します。',
    (4, '契約による設計'): 'preconditionはcallerが満たす入力条件、postconditionはoperationが成功後に保証する結果、invariantはobject/moduleが常に保つ性質です。契約違反と通常のbusiness errorを分け、runtime assertion、type、test、documentationへ反映します。強すぎるpreconditionや曖昧なside effectは再利用性を下げます。',
    (4, '型による検証'): 'refinement typeはbase typeへpredicateを加え、dependent typeはvalueに依存する型を表します。phantom typeやtypestateはruntime dataを増やさず、compile時state transitionや単位を区別できます。すべてを型へ押し込むと可読性とcompile costが増えるため、critical invariantへ選択的に適用します。',
    (4, '分散システムの形式化'): 'TLA+はstate variable、初期条件、next-state relation、temporal propertyでsystem behaviorを集合として記述します。PlusCalはalgorithm風syntaxからTLA+へ変換します。message loss、retry、reorder、leader change等を小modelへ含め、safety/livenessとfairnessをmodel checkerで検証します。',
    (4, '形式手法の実務導入'): '形式手法は全codeを証明する二択ではなく、金銭・権限・consensus・workflow等の高riskなprotocolへ抽象modelを適用できます。仕様review、state machine、property test、model checking、proofをriskに合わせて段階化します。反例が実装testへ移植され、設計変更へ繋がる運用を作ります。',

    # 05 Computer Architecture
    (5, 'デジタル論理と数表現'): 'logic gateはboolean演算を回路で実現し、組合せ回路は現在入力、順序回路はflip-flop等のstateにも依存します。二の補数はsigned integer演算を統一し、IEEE 754 floating pointは符号・指数・仮数で広い範囲を近似します。overflow、rounding、NaN、subnormal、associativity破れをsoftwareで扱います。',
    (5, '命令セットアーキテクチャ'): 'ISAはinstruction、register、memory/addressing、exception、privilegeを定義するhardware-software contractです。RISCは単純なinstructionとload/store、CISCは複雑instructionを含む傾向ですが、現代CPU内部ではmicro-opへ変換されることもあります。compiler、OS、binary互換性はISAとABIの組で成立します。',
    (5, 'CPUパイプライン'): 'pipelineはinstruction処理をfetch/decode/execute/memory/writeback等へ分け、複数instructionを重ねてthroughputを上げます。data/control/structural hazardにはforwarding、stall、branch prediction、out-of-order実行で対処します。予測失敗やdependency chainはpipelineを空にし、tail latencyやspectre系riskにも関わります。',
    (5, 'キャッシュとメモリ階層'): 'cacheは時間・空間局所性を利用し、cache line単位で遅いmemoryからdataを保持します。direct/set-associative/full-associativeで検索costとconflict missが変わります。working set、stride、alignment、prefetch、write policyを理解し、algorithmのO記法が同じでも実性能が大きく違う理由を説明します。',
    (5, '仮想記憶ハードウェア'): 'MMUはvirtual addressをpage tableでphysicalへ変換し、TLBが最近の変換をcacheします。multi-level page tableは疎なaddress空間のmemoryを節約し、huge pageはTLB reachを増やす一方でfragmentationを生みます。page fault、protection bit、ASID/PCIDがOSの隔離と性能を支えます。',
    (5, 'マルチコアとメモリ一貫性'): '各coreのprivate cacheが同じlineを持つため、MESI等のcoherence protocolで一つのmemory像を保ちます。ただしprogram order通りに他coreから見えるとは限らず、memory modelとfence/atomicがhappens-beforeを作ります。別変数でも同一cache lineにあるfalse sharingは性能を大きく落とします。',
    (5, 'I/Oとバス'): 'deviceはmemory-mapped registerやportを通じて制御され、interruptで完了を通知します。DMAはCPUを介さずdeviceとmemory間を転送し、IOMMUがaddress変換と隔離を提供します。PCIeはlaneとpacketでdeviceを接続し、bandwidth、latency、queue、interrupt moderationがI/O性能を決めます。',
    (5, 'NUMAと大規模サーバ'): 'NUMAではCPU socketごとにlocal memoryがあり、remote accessは遅く帯域も共有されます。threadとmemory allocationのfirst-touch、CPU affinity、interrupt placementを合わせる必要があります。単純にthread数を増やすとcross-socket traffic、lock contention、cache coherenceで逆に遅くなる場合があります。',
    (5, 'SIMDとベクトル化'): 'SIMDは一つのinstructionで複数data elementへ同じ演算を適用します。compilerのauto-vectorizationには連続access、alias不在、依存なし、整列等が必要です。branchをmaskへ変え、structure-of-arrays、loop tiling、remainder処理を使い、memory bandwidthとの均衡を測ります。',
    (5, 'アクセラレータと異種計算'): 'GPU/TPU/NPUは特定のdata-parallel演算を高throughputで実行しますが、host-device transferと専用memoryがboundary costになります。workloadのarithmetic intensity、batch、latency、model support、precision、programming ecosystemを評価します。全処理を移すのではなく、hot kernelだけoffloadする設計も重要です。',

    # 07 Concurrency
    (7, '並行性の基本モデル'): 'concurrencyは複数taskの進行が重なる構造、parallelismは同時に複数hardwareで実行することです。共有stateへのread/writeが同期なしにinterleaveするとrace conditionが起きます。execution traceとhappens-beforeを使い、結果がscheduleに依存する箇所を特定します。',
    (7, 'ロックと同期プリミティブ'): 'mutexはcritical sectionを一threadに限定し、semaphoreは有限permit、condition variableはpredicate変化を待ちます。read-write lockはread多数時に有利ですがwriter starvationやoverheadがあります。lockが守るinvariant、acquire順、待ち中のresource、exception時解放を明示します。',
    (7, 'アトミック操作とメモリモデル'): 'atomic read-modify-writeは途中状態を他threadから観測させず、compare-and-swapは期待値一致時だけ更新します。memory orderはatomic操作前後の通常memory visibilityを制約し、acquire/releaseやsequential consistencyを選びます。単一atomic変数の安全性だけでは複数変数のinvariantを自動で守れません。',
    (7, 'デッドロック・ライブロック・飢餓'): 'deadlockは相互排他、保持待ち、非preemption、循環待ちが揃うと起きます。global lock order、try-lock、timeout、resource hierarchyで予防します。livelockは動いているが進まず、starvationは特定taskが資源を得られない状態で、backoffとfairnessを測ります。',
    (7, 'Lock-free・Wait-free'): 'lock-freeはsystem全体の誰かが進み、wait-freeは各operationが有限stepで完了する進行保証です。CAS loopではABA、memory reclamation、contention retryが難所です。hazard pointerやepoch-based reclamationで他threadが参照中のnodeを安全に解放し、性能は低競合/高競合で測ります。',
    (7, 'Actor・CSP・メッセージパッシング'): 'actorはstateをmailboxごとに隔離しmessageを逐次処理、CSPはprocess間のchannel communicationを中心にします。共有memory raceを減らせますが、mailbox増大、message順、failure propagation、request-response deadlockが残ります。supervisionやstructured lifecycleでchild failureとrestartを管理します。',
    (7, 'タスクスケジューリング'): 'thread poolはtask作成costを抑え、work stealingはidle workerが他queueからtaskを奪います。CPU-boundとI/O-boundを同じpoolへ混ぜるとstarvationしやすく、priority inversionは低優先taskのlockが高優先を止めます。queue length、service time、fairness、cancel、backpressureを設計します。',
    (7, '並列アルゴリズム'): 'parallel algorithmはdata/taskを分割し、local計算とmerge/synchronizationを組みます。map-reduce、prefix sum、fork-joinは代表patternです。Amdahlの法則によりserial部分がspeedup上限となり、粒度が小さすぎるとschedule/communication overheadが支配します。',
    (7, '非同期I/O'): 'callback、Promise/Future、async-awaitはI/O完了時にcontinuationを再開し、待ちthreadを減らします。非同期は自動でparallel CPU処理になるわけではありません。structured concurrencyはchild taskをscopeへ束ね、cancel、timeout、error、resource解放を親のlifecycleに従わせます。',
    (7, '並行プログラムの検証とデバッグ'): 'race detectorは実行traceから未同期accessを検出しますが、通らなかったinterleavingは保証しません。deterministic scheduler、stress、linearizability check、model checkingでschedule spaceを探索します。timestampだけでなくthread/task ID、lock、queue、state transitionをtraceへ残します。',

    # 08 PL / Types
    (8, '構文・意味論・評価'): 'abstract syntaxはprogramの構造をtreeとして表し、operational semanticsは小step/大stepで評価遷移を定義します。denotational semanticsはprogramを数学的対象へ写します。call-by-value/name/need等の評価戦略は副作用、終了性、性能を変えるため、言語仕様の一部です。',
    (8, 'ラムダ計算'): 'lambda calculusは変数、関数抽象、適用だけで計算を表します。alpha変換はbound変数名変更、beta reductionは引数置換、capture-avoiding substitutionが必要です。Church encodingはbooleanや数、pairを関数だけで表し、関数がdataとcontrolの両方を表現できることを示します。',
    (8, '静的型付けと動的型付け'): 'static typingは実行前に型ruleを検査し、dynamic typingはruntime valueへ型tagを持たせます。型安全性はprogress（正しいprogramは値か進める）とpreservation（step後も型が保たれる）で示せます。gradual typingはtyped/untyped境界にruntime checkを入れます。',
    (8, '多相性とGenerics'): 'parametric polymorphismは型に依存しない一様な実装、ad-hoc polymorphismはoverload/typeclass/trait等で型ごとにbehaviorを変えます。subtypingは値集合の包含と代入可能性を扱い、varianceはcontainer型のsubtype関係を決めます。mutable APIではcovarianceが危険になる理由を具体例で確認します。',
    (8, '型推論'): '型推論はexpressionから型constraintを生成し、unificationで型変数を一致させます。Hindley-Milnerではlet-bound expressionをgeneralizeし、principal typeを得られます。subtyping、overload、effect、higher-rank型を加えると推論は複雑化し、annotationとのbalanceが必要です。',
    (8, '代数的データ型とパターンマッチ'): 'product typeはfieldが同時に存在、sum typeはvariantの一つを表し、再帰型でlist/treeを定義します。pattern matchは構造分解とbranchを同時に行い、exhaustiveness checkが未処理stateを防ぎます。GADTはconstructorごとにresult typeを精密化し、typed AST等を表現します。',
    (8, '効果と副作用'): 'referential transparencyはexpressionを値で置換しても意味が変わらない性質です。Monadはeffectful計算の順序を型付きで合成する一方式、effect systemは関数が行うI/O、exception、state等を型へ記録します。handlerはeffectの解釈を外部化し、testや複数runtimeへ差し替えられます。',
    (8, '所有権・ライフタイム・線形型'): 'linear typeは値を正確に一度、affine typeは高々一度使う制約で、file、lock、memory等の資源管理を型へ移します。ownershipとborrowはaliasingと寿命を制限してuse-after-free/data raceを防ぎます。APIではresource transitionを型stateとして表し、close忘れや二重利用をcompile時に防ぎます。',
    (8, 'オブジェクト指向の型理論'): 'nominal typingは宣言名と継承、structural typingはmember形で互換性を決めます。dynamic dispatchはruntime receiver型からmethodを選び、LSPはsubtypeがbaseの期待を破らないbehavior contractです。row polymorphismはrecordの既知fieldと追加fieldを型で扱います。',
    (8, '言語設計とDSL'): 'DSLは特定domainの概念を直接表す小言語で、internal DSLはhost languageの構文、external DSLは独自parserを使います。syntaxの美しさだけでなく、error message、tooling、versioning、sandbox、interoperability、escape hatchを設計します。macroは生成時phaseと衛生性を理解して使います。',

    # 16 Database
    (16, 'リレーショナルモデルとSQL'): 'relational modelはrelationをtuple集合として扱い、keyとconstraintでidentityと整合性を表します。relational algebraのselection、projection、join等がSQL queryの理論基盤です。SQLはNULLとthree-valued logic、bag semantics、transaction contextを持つため、純粋集合演算との差を理解します。',
    (16, 'スキーマ設計と正規化'): 'functional dependency X→YはXがYを一意に決める関係です。normalizationは重複とupdate anomalyを分解で減らし、lossless joinとdependency preservationを確認します。read性能や分析目的でdenormalizeする場合、source of truth、更新方法、再構築、整合性監視を設計します。',
    (16, 'Indexと実行計画'): 'B+tree indexはsorted keyでpoint/range検索、hash indexはequalityへ適します。optimizerは統計からcardinalityとcostを推定し、scan、join order、join algorithmを選びます。selectivity、composite key順、covering、partial/function index、stale statistics、parameter sensitivityをplanと実測で確認します。',
    (16, 'TransactionとIsolation'): 'ACIDはatomicity、consistency、isolation、durabilityで、isolationはconcurrent transactionの観測を制限します。lock方式とMVCCでdirty/non-repeatable/phantom/write skew等の現象が変わります。業務invariantがserializableを必要とするか、explicit lockやunique constraintで守れるかを具体的に判断します。',
    (16, 'Storage Engine'): 'databaseは固定size pageへrecord/indexを配置し、buffer poolがhot pageをmemoryへcacheします。WALをdata pageより先に永続化してcrash recoveryし、checkpointでrecovery距離を短くします。LSM系はmemtableとsorted runをcompactionしwriteを効率化しますが、read amplificationとcompaction負荷が増えます。',
    (16, 'Replication・Partition・Backup'): 'replicationは同じdataのcopyを複数nodeへ持ち、sync/async方式でdurabilityとlatencyが変わります。partition/shardingはkeyでdataを分けscaleしますが、cross-shard query、hot key、rebalancingが難しくなります。backupはfull/incremental/WAL archiveを組み、PITRとrestore testでRPO/RTOを満たします。',
    (16, 'Key-Value・Document・Wide-column'): 'key-value storeはkey中心、document DBはnested documentとsecondary query、wide-columnはpartition key内のordered sparse rowを扱います。schema-lessはschema不要ではなくapplication側へ責任が移ります。access patternからpartition key、item size、consistency、index、hot partition、transaction範囲を先に設計します。',
    (16, 'CacheとIn-memory Store'): 'cache-asideはmiss時にapplicationがsourceから読み書きし、write-through/backは更新経路を変えます。TTLとLRU/LFU等のevictionはfreshnessとhit rateを調整します。stampedeにはsingle-flight、jitter、early refresh、negative cacheを使い、cacheを正しさの唯一sourceにしない設計が基本です。',
    (16, '全文検索・Vector検索'): 'inverted indexはtermからdocument posting listを引き、tokenization、normalization、BM25等でrankingします。vector検索はembedding近傍をANN indexで探索し、exact recallとのtrade-offがあります。hybrid search、filter、rerank、evaluation set、freshness、permission trimmingをend-to-endで設計します。',
    (16, 'Database Reliability・Security'): 'connection poolはDB接続数を制限し、待ち行列とtimeoutを作ります。schema changeはlock、table rewrite、backfill、replica lagを考えexpand-contractで進めます。encryption、least privilege、row/tenant境界、audit、secret rotation、backup access、restore権限までdata securityに含めます。',

    # 17 Distributed Systems
    (17, '分散システムの前提'): '分散systemではnetwork delayに上限を仮定できず、message loss/duplication/reorderとnode crashが独立に起きます。相手が遅いのか死んだのか完全には区別できないため、timeoutはfailure detectorの推定です。partial failureを通常caseとしてretry、idempotency、reconciliation、observabilityを組み込みます。',
    (17, 'CAP・PACELC・整合性モデル'): 'network partition中にlinearizable consistencyと常時availabilityを同時には保証できないのがCAPの核心です。PACELCはpartition時だけでなく通常時のlatency-consistency trade-offも表します。read-your-writes、monotonic read、causal、eventual、linearizable等をbusiness operationごとに選びます。',
    (17, 'Replication'): 'leader-followerは一nodeがwrite順を決め、multi-leaderは複数拠点writeとconflict解決、leaderlessはquorumでread/writeします。replication log、ack条件、lag、read repair、anti-entropy、conflict resolutionが保証を決めます。failover時のsplit-brainとlost acknowledged writeを検証します。',
    (17, 'Consensus'): 'consensusは複数nodeがfailure下でも同じ値/log順に合意する問題です。Raftはterm、leader election、replicated log、commit indexでsafetyを理解しやすく分解します。majorityを失うと安全のため進めない点、membership change、snapshot、disk durability、clock非依存を扱います。',
    (17, 'Clock・Ordering・ID'): 'physical clockはdrift/skewがあり、timestampだけで因果順序を保証できません。Lamport clockはhappens-beforeを反映するscalar、vector clockはconcurrent eventを識別、HLCはphysical timeとlogical orderを組み合わせます。UUID/Snowflake等は一意性、sortability、coordination、privacy leakageを比較します。',
    (17, 'Messaging基礎'): 'queueはconsumer間でworkを分配し、logはordered eventを保持して複数consumerが独立offsetで読みます。at-most-onceはloss可能、at-least-onceはduplicate可能、exactly-onceは定義したboundary内でdedupe/transactionを組み合わせた性質です。ordering範囲、ack、visibility timeout、DLQ、backpressureを設計します。',
    (17, 'Kafka・Stream Processing'): 'Kafka topicはpartitionごとのappend-only logで、offsetがposition、consumer group内ではpartitionを一consumerが担当します。retentionによりreplayでき、keyがpartitionと局所orderingを決めます。stream processingではstate store、changelog、window、watermark、rebalance、schema evolution、exactly-once boundaryを扱います。',
    (17, 'Idempotency・Saga・Outbox'): 'idempotency keyとinbox tableは重複command/messageの副作用を一度に抑えます。Sagaは複数local transactionをsequenceし、失敗時にcompensating actionでbusiness状態を戻します。transactional outboxはDB更新と送信予定recordを同じtransactionへ入れ、後でpublisherが配送します。',
    (17, 'Distributed Cache・Coordination'): 'consistent hashingはnode増減時のkey移動を抑え、virtual nodeで分布を均します。leaseは期限付きownership、distributed lockはfencing tokenなしではpause後の古いownerが書く危険があります。membership、leader election、configurationはconsensus serviceへ限定し、coordination dependencyを増やしすぎないようにします。',
    (17, '分散システムのテストと運用'): 'distributed bugは特定のmessage順、pause、partition、clock、retryでのみ現れます。fault injection、deterministic simulation、history checker、Jepsen的linearizability検証で保証を試します。systemはrepair/reconciliation loopを持ち、operatorがevent、version、ownership、lagを追跡できるようにします。',

    # 19 Containers / Kubernetes
    (19, 'Container基礎'): 'containerはnamespaceでprocess、network、mount等の見え方を分け、cgroupでCPU/memory/I/O使用を制限します。imageはread-only layerのstack、runtimeがroot filesystemとprocessを起動します。kernelはhostと共有するためVMほどの隔離ではなく、capability、seccomp、user namespace等が重要です。',
    (19, 'Docker Build・Runtime'): 'Dockerfileはbuild contextからlayerを生成し、cache keyはinstructionとinputに依存します。multi-stage buildでcompiler/toolを最終imageから除き、non-root、read-only filesystem、pinned base、small contextでattack surfaceを減らします。volume、network、signal、PID1、healthcheck、resource limitをruntime contractとして扱います。',
    (19, 'Kubernetes Architecture'): 'KubernetesはAPI serverへdesired stateを保存し、controllerがactual stateとの差をreconcileします。etcdはcluster state、schedulerは未配置Podのnode選択、kubeletはnode上でPodを実現します。宣言は即時成功ではなくeventual convergenceなので、status/condition/eventを読んで障害を追います。',
    (19, 'Workload Resource'): 'Podは一緒にscheduleされnetwork/volumeを共有するcontainer群です。Deploymentはstateless replicaとrolling update、StatefulSetはstable identity/order、Job/CronJobは完了型taskを管理します。restart policy、readiness/liveness/startup probe、termination grace、PodDisruptionBudgetをlifecycleへ合わせます。',
    (19, 'Service・Ingress・Networking'): 'Serviceはlabel selectorでPod集合へstable virtual IP/DNSを提供し、kube-proxy/eBPF等が転送します。Ingress/Gateway APIはHTTP/TLS route、CNIはPod network、NetworkPolicyは許可通信を定義します。source IP、session affinity、DNS、MTU、cross-zone、egressをpacket pathで確認します。',
    (19, 'Config・Secret・Storage'): 'ConfigMap/Secretはcontainer imageと環境固有設定を分離しますが、Secretはbase64だけでは暗号化ではありません。CSIはstorage driver、PV/PVCは供給とclaimを抽象化します。mount更新、application reload、access mode、zone binding、snapshot、backup、stateful failoverを設計します。',
    (19, 'Scheduling・Scaling・Resource'): 'requestはschedulerが予約に使い、limitはruntime制限です。CPU limitはthrottling、memory limit超過はOOM killにつながります。HPAはmetricでreplica、VPAはresource値、cluster autoscalerはnode数を調整し、affinity/taintでplacementを制御します。',
    (19, 'Security・Policy・Supply Chain'): 'Kubernetes RBACはAPI action、service accountはworkload identity、Pod Security/admission policyは危険なspecを拒否します。image digest、signature、SBOM、vulnerability、registry accessを供給網で検査します。hostPath、privileged、capability、secret mount、metadata access、cross-namespace trustを最小化します。',
    (19, 'Service Mesh・Multi-cluster'): 'service meshはproxy/data planeとcontrol planeでmTLS、retry、traffic split、telemetryを提供します。sidecar/ambient等の方式でresourceと運用costが異なります。application retryとの重複、timeout budget、identity、certificate rotation、debug path、failure dependencyを評価し、必要な機能だけ導入します。',
    (19, 'Platform Engineering'): 'internal developer platformはinfrastructureを隠すだけでなく、teamが安全なgolden pathをself-serviceで利用できるproductです。service template、catalog、environment、policy、observability、costを一貫したAPI/UIへまとめます。adoption、lead time、failure rate、developer satisfactionを測り、強制platformではなく利用価値を改善します。',

    # 20 DevOps / Delivery
    (20, 'DevOps原則とValue Stream'): 'DevOpsは役職名ではなく、開発と運用のfeedback loopを短くし、flow、quality、learningを高める考え方です。ideaからproduction outcomeまでのvalue streamを可視化し、queue、handoff、manual approval、reworkを測ります。小batch、automation、shared ownership、production feedbackでlead timeとriskを同時に下げます。',
    (20, 'Git内部とWorkflow'): 'Gitはblob、tree、commit、tagをcontent-addressed objectとして保存し、branchはcommitへの可変pointerです。mergeはhistoryを統合し、rebaseはcommitを別base上へ再生成します。trunk-basedは小変更を頻繁に統合し、feature flagで未完成を隠します。protected branch、signed commit、review、release tagを目的から設計します。',
    (20, 'Build System'): 'build systemはtargetとdependency graphを解析し、変更影響だけを再実行します。hermetic buildは宣言したinput以外へ依存せず、同じinputから同じartifactを作ります。content-addressed cache、remote execution、sandbox、toolchain pin、generated source、environment variableを管理します。',
    (20, 'CI Pipeline'): 'CIは各変更を早く統合し、自動build/test/static/security checkでfeedbackします。pipelineはfast gateを先にし、change graphで対象testを絞り、parallel/shard/cacheで時間を減らします。flaky testをretryで常態化せず、failure artifact、ownership、quarantine期限、merge policyを整えます。',
    (20, 'Artifact・Package・Registry'): 'artifactはbuild後に変えないimmutable unitで、同じdigestをdevからproductionへpromoteします。semantic versionは互換性意図を表し、registryはaccess、retention、scan、signature、provenanceを管理します。latest tagや環境ごとの再buildを避け、SBOMとsource/build identityを結びます。',
    (20, 'Deployment Strategy'): 'rollingは順次置換、blue-greenは環境切替、canaryは一部trafficへ段階投入します。feature flagはdeployとreleaseを分離します。readiness、connection drain、session/data compatibility、metric gate、automatic rollback、manual abort、observability lagをstrategyへ含めます。',
    (20, 'Database・Schema Release'): 'schema変更はold/new applicationが同時稼働できる互換期間を作ります。expandでnullable/new table等を追加し、dual read/writeやbackfillを行い、contractで旧columnを削除します。large migrationのlock、WAL、replica lag、retry、verification、rollback不可操作を事前に測ります。',
    (20, 'GitOps・Environment Management'): 'GitOpsはdesired stateをGitでreviewし、controllerがenvironmentを継続reconcileします。promotionは同一artifactのversion/referenceを環境間で進め、manual driftを検知・修復します。secret、emergency change、rollback、multi-cluster、generated manifest、ownershipをprocessとして定義します。',
    (20, 'Software Supply Chain Security'): '供給網はsource、dependency、build runner、artifact、registry、deploy credentialの各段階で改ざんされ得ます。pinned dependency、isolated builder、least privilege、SBOM、signature、attestation、provenance policyで信頼chainを作ります。scan結果だけでなく、修正SLAとexception expiryを運用します。',
    (20, 'Release Engineering Metrics'): 'deployment frequencyとlead timeはflow、change failure rateとMTTRはstabilityを示すDORA系metricです。数字を個人評価に使うとgamingされるため、system改善のtrendとして扱います。rollback率、canary abort、defect escape、pipeline wait、verification timeをvalue streamと関連付けます。',

    # 22 Observability
    (22, 'Observabilityの考え方'): 'monitoringは既知のfailureをsignalで監視し、observabilityは外部出力から未知の内部状態を推定できる性質です。telemetryを増やすだけでなく、request、user、deploy、dependency、resourceを同じcontextで関連付けます。debuggabilityを設計時の品質属性として、質問に答えるまでの時間を測ります。',
    (22, 'Logging'): 'structured logはmessageだけでなくtimestamp、level、event name、service、request ID、entity ID等をfieldとして出します。errorのcause/stackとbusiness contextを残し、password/token/PIIをredactします。sampling、retention、cardinality、schema evolution、clock、duplicate logを管理し、logを唯一のmetric sourceにしません。',
    (22, 'Metrics'): 'counterは累積event、gaugeは現在値、histogramは値の分布をbucketで集計します。labelはdimensionを増やしますがuser ID等の高cardinalityはcostとquery性能を破壊します。REDはrate/error/duration、USEはutilization/saturation/errorでserviceとresourceを観測します。',
    (22, 'Distributed Tracing'): 'traceは一requestのend-to-end経路、spanは個々のoperationで、parent/childとcontext propagationにより因果関係を表します。critical path、fan-out、retry、queue wait、DBをspan timingから特定します。head/tail sampling、PII、async boundary、clock skew、missing contextを考慮します。',
    (22, 'OpenTelemetry'): 'OpenTelemetry API/SDKはapplication計装、Collectorは受信・加工・batch・export、semantic conventionは共通field名を定義します。agent/vendor固有codeを減らせますが、resource attribute、sampling、propagator、processor、retry queue、backpressureを設計する必要があります。',
    (22, 'Profiling'): 'CPU profilingはsampled stackから時間を使うcode path、heap/allocation profilingはmemory生成と保持を示します。wall-clock、off-CPU、lock、I/O profileを使い分けます。continuous profilingはproduction workloadのrare hotspotを捉えますが、symbol、overhead、privacy、version/deploy annotationを整えます。',
    (22, 'Dashboard Design'): 'dashboardは一画面へすべて詰めず、user impact→service health→dependency/resource→detailのdrill-downを作ります。absolute値とrate、percentileとdistribution、現在とbaseline、deploy annotationを組み合わせます。各panelがどのdecisionを支えるかを明示し、unused dashboardを整理します。',
    (22, 'Alert Engineering'): 'static threshold、rate of change、anomaly、SLO burn-rateをsignal性質に合わせます。alertはdeduplicate/groupし、severity、owner、routing、maintenance、inhibitionを定義します。通知が鳴った後に人が取るactionがなければpageにせず、alert qualityをprecision/recallと対応時間で改善します。',
    (22, 'Telemetry Pipeline'): 'agent/collectorはtelemetryをbufferし、network障害時にretryしますが、queue容量を超えるとlossまたはapplication影響が起きます。batch、compression、sampling、aggregation、tiered retentionでcostを制御します。pipeline自身のthroughput、drop、lag、cardinality、storage quotaも監視します。',
    (22, 'Observability-driven Debugging'): 'debuggingは症状から仮説を作り、log/metric/trace/profileを相互に検証して反証します。deploy、traffic、dependency、resource、tenant sliceで時系列を比較し、correlationとcausationを区別します。incident後は不足telemetryを追加し、同じ質問へ次回より速く答えられるようにします。',

    # 23 Performance
    (23, '性能目標と測定'): 'latencyは一処理時間、throughputは単位時間量、utilizationは資源使用率、saturationは待ちが発生する状態です。平均はtailを隠すためp50/p95/p99とdistributionを使います。measurement自身のoverhead、clock resolution、coordinated omission、environment差を管理します。',
    (23, 'Benchmark設計'): 'microbenchmarkは小operation、macrobenchmarkは実workloadを測ります。JIT/GC/cache warm-up、CPU frequency、background load、input distributionを固定・記録します。複数runとconfidence interval、effect sizeを使い、benchmark codeがoptimizerに消されていないか、productionを代表するか確認します。',
    (23, 'CPU Profiling'): 'sampling profilerは一定間隔でstackを採り、flame graphの幅がsample比率を示します。user/system/off-CPU、instruction、branch miss、cache missを組み合わせます。hot functionだけでなく、call path、algorithm、data layout、lock、serialization、syscallへ原因を遡ります。',
    (23, 'Memory Profiling'): 'heap snapshotは時点のobject graph、allocation profileは生成rate、retained sizeは解放を妨げる参照を示します。leakは時間とともにlive setが増える現象で、cache成長やfragmentation、native memoryと区別します。load/soak下でGC後baselineを比較します。',
    (23, 'GC Performance'): 'GCはallocationとlive setを追跡し、mark/copy/compact等で回収します。young generationは短命objectを効率化し、concurrent GCはpauseを減らす代わりにCPUとbarrier costを使います。heapを大きくするとGC頻度は下がりますがmemoryとworst pauseが増え、allocation削減が根本改善になる場合があります。',
    (23, 'I/O・Network Performance'): 'I/O性能はsyscall、context switch、copy、buffer、device/network latency、queueで決まります。batching、buffering、zero-copy、async I/O、connection reuseでoverheadを減らします。大bufferはthroughputを上げてもtailとmemoryを悪化させるため、backpressureとqueue depthを測ります。',
    (23, 'Database Performance'): 'DB latencyはparse/plan、lock wait、buffer/cache hit、I/O、network、result serializationへ分解できます。execution planとactual row、index、statistics、join、N+1を確認します。pool sizeを増やしすぎるとDB内concurrencyとcontext switchが増えるため、throughput上限とqueueを合わせます。',
    (23, 'Queueing Theory'): 'Littleの法則L=λWは平均系内数、到着率、滞在時間を結びます。利用率が1へ近づくと小さなvarianceでもqueueとtail latencyが非線形に増えます。service time分布、burst、bounded queue、priority、load sheddingをmodel化し、headroomを持たせます。',
    (23, 'Load Test・Capacity'): 'workload modelはrequest mix、arrival pattern、session、data size、cache、dependencyを本番に近づけます。rampで曲線、spikeで急増、soakでleak、stressでfailure modeを確認します。client側が目標rateを出せているか、coordinated omission、warm-up、autoscaling delay、recoveryを測ります。',
    (23, 'Performance Optimization Process'): '最初にbaselineとSLOを固定し、profileから一つのbottleneck仮説を立て、controlled experimentで変更します。局所micro改善がend-to-endへ効くか、correctnessやcostを悪化させないか確認します。regression benchmarkとproduction telemetryで改善を継続的にguardします。',

    # 26 Data Engineering
    (26, 'Data Architecture'): 'OLTPは小さなtransactionと整合性、OLAPは大量scan/aggregationへ最適化されます。warehouseは整形済み分析data、lakeはobject storage上の多様なraw/curated data、lakehouseはtable formatでtransaction/metadataを加えます。data productごとにowner、contract、SLO、consumerを定義します。',
    (26, 'Ingestion'): 'batch ingestionは一定期間ごと、streamはevent発生に近い連続取り込み、CDCはDB logからchangeを取得します。source offset/checkpoint、schema evolution、ordering、duplicate、late data、backfillを扱います。raw dataをimmutableに保つと再処理と監査が容易になります。',
    (26, 'ETL・ELT・Transformation'): 'ETLはload前、ELTはwarehouse/lakehouseへload後にtransformします。pipelineをDAGとしてdependencyとartifactを明示し、partition単位のincremental処理とidempotent overwrite/mergeで再実行可能にします。business logicをtestし、code/versionとoutput lineageを結びます。',
    (26, 'Data Modeling for Analytics'): 'star schemaは中心のfact tableとdescriptive dimensionを分け、metricのgrainを明確にします。slowly changing dimensionは属性履歴の保持方式をtypeで選びます。semantic layerでmetric定義を一元化し、同じ売上・user数がdashboardごとに違う問題を防ぎます。',
    (26, 'Batch Processing'): 'batch engineはdataをpartitionへ分け、map/shuffle/reduce等で分散処理します。shuffleはnetworkとdiskを大量に使い、skewed keyは一taskを遅らせます。file size、partition pruning、join strategy、memory spill、retry、speculative executionをprofileします。',
    (26, 'Stream Processing'): 'event timeは発生時刻、processing timeは処理時刻で、windowとwatermarkが遅延eventをどこまで待つかを決めます。stateful operatorはkeyごとの状態をcheckpointし、source/sinkとのtransactionでexactly-once相当を作ります。late update、retraction、out-of-order、state growthを設計します。',
    (26, 'Orchestration'): 'orchestratorはtask dependency、schedule、retry、timeout、backfill、artifactを管理します。単なるcron連鎖ではなく、data partition readinessとidempotencyを基準に実行します。catchupによる負荷集中、sensor polling、cross-DAG dependency、manual rerun、partial successを運用します。',
    (26, 'Data Quality・Observability'): 'qualityはfreshness、completeness、uniqueness、validity、distribution、referential integrity等で定義します。source contractとtransform各段にcheckを置き、failureをconsumer impactとlineageへ関連付けます。単一row errorとsystemic driftで対応を分け、quarantineとreprocessを用意します。',
    (26, 'Metadata・Governance・Security'): 'catalogはdatasetのschema、owner、description、usage、lineageを検索可能にします。classificationでPII/機密度を付け、role/purposeに応じたaccess、masking、row/column policyを適用します。retention、legal hold、delete、consentをcopyやderived dataまで追跡します。',
    (26, 'Cost・Performance・DataOps'): 'columnar format、compression、partition、clustering、predicate pushdownでscan量を減らします。small file問題、idle cluster、shuffle、duplicate pipeline、excess retentionをcostへ変換します。SQL/code lint、unit/data test、sample environment、CI、deployment、rollbackをdata pipelineにも適用します。',

    # 29 MLOps
    (29, 'ML LifecycleとReproducibility'): 'experimentを再現するにはcode commit、data snapshot/query、feature version、configuration、seed、environment、hardware、metricを記録します。nondeterministic GPU operationやexternal APIも結果差を生みます。tracking systemでrun比較を行い、best resultだけでなく失敗runとselection biasを残します。',
    (29, 'Feature・Data Pipeline'): 'feature storeはoffline training用historical featureとonline serving用低latency featureを共通definitionで管理します。point-in-time correct joinで未来情報を防ぎ、offline/online skew、freshness、default、backfillを検証します。label delayとfeedback loopをdata contractへ含めます。',
    (29, 'Training Infrastructure'): 'distributed data parallelはmodel copyごとにbatchを処理しgradientをall-reduceします。checkpointはmodel/optimizer/scheduler/RNG stateを保存し、preemptionやfailureから再開します。mixed precisionでthroughputとmemoryを改善しますが、overflow、communication、data loader、stragglerをprofileします。',
    (29, 'Model Registry・Promotion'): 'registryはmodel artifactだけでなくtraining data、code、metric、signature、license、approval、deployment historyを紐付けます。candidateをoffline gate、shadow/canary、business reviewで段階promoteし、immutable versionとrollbackを保ちます。modelとpre/post-processingを一つのcontractとしてversion化します。',
    (29, 'Model Serving'): 'online servingは低latency request、batchは大量offline predictionです。serverはmodel load、preprocess、batching、inference、postprocess、cacheを行います。autoscaling metric、cold start、queue、timeout、fallback、multi-model memory、version routingをSLOへ合わせます。',
    (29, 'GPU・Accelerator Operation'): 'GPU utilizationだけでなくSM occupancy、memory use/bandwidth、kernel gap、data transfer、queueを観測します。schedulerはdevice、memory、topology、MIG等を考慮し、multi-tenancyのisolationとfragmentationを管理します。idle高価資源とlatency SLOをbatch/priority/preemptionで均衡させます。',
    (29, 'Inference Optimization'): 'quantizationは低bit表現、distillationはteacher behaviorを小modelへ、pruningはparameter/structure削減を行います。compiler/kernel fusion、KV cache、continuous batching、speculative decoding等で速度を上げます。task/slice別quality、calibration、hardware実測、fallbackを必ず比較します。',
    (29, 'Model Monitoring'): '本番ではinput distribution、feature quality、prediction distribution、latency/error、label到着後のperformanceを監視します。data driftが必ず性能低下を意味せず、concept driftは関係そのものの変化です。sliceとtime windowでalertし、retrain、rollback、human reviewのactionへ繋げます。',
    (29, 'AI Evaluation Platform'): 'evaluation platformはversioned dataset、runner、model/prompt/config、metric/judge、artifact、comparison UIを統合します。deterministic checkerとhuman/LLM judgeを組み合わせ、seed、temperature、sample数でvarianceを扱います。production failureをregression setへ追加し、deploy gateとonline experimentへ接続します。',
    (29, 'AI Governance・Security・Cost'): 'AI assetのowner、purpose、data lineage、model card、risk tier、approval、access、retentionを管理します。training data poisoning、model theft、prompt/tool abuse、supply chainをthreat modelへ含めます。GPU hour、token、storage、egress、人手reviewをquality metricと紐付け、unit economicsで最適化します。',

    # 30 Developer Tooling
    (30, 'Developer Experienceの測定'): 'developer productivityをcommit数で測らず、setup time、build/test feedback、deploy lead time、interrupt、cognitive load、satisfaction、outcomeを組み合わせます。surveyとtelemetryを匿名・集約し、tool導入前後でtask時間とfailureを比較します。local最適がsecurity/operationsへ負担を移していないか確認します。',
    (30, 'Editor・IDE・LSP'): 'LSPはeditorとlanguage server間でJSON-RPCを使い、completion、hover、definition、diagnostics、rename等を標準化します。document versionとincremental change、position encoding、cancel、workspace indexを扱います。syntax/semantic analysisをcacheし、入力中でも低latencyに部分結果を返します。',
    (30, 'Debugger'): 'debuggerはbreakpointでexecutionを停止し、stack frame、local、memory、thread、expressionを観察します。source map/debug infoがmachine codeとsource位置を対応させます。conditional breakpoint、watchpoint、step semantics、optimized code、async stack、remote attachを理解し、再現scriptと組み合わせます。',
    (30, 'Static Analysis'): 'static analyzerはAST/CFG/call graph/data-flowを構築し、未実行でもbug patternやpolicy違反を探します。interprocedural、alias、taint、symbolic executionを強くするとprecisionとcostが増えます。ruleにはseverity、confidence、example、autofix、安全なsuppression、baselineを設計します。',
    (30, 'Formatter・Linter・Code Action'): 'formatterはparseしたsyntax treeを決定的に再印字し、style debateを自動化します。linterはsemantic/policy rule、code actionはdiagnosticから修正editを返します。comment保持、range formatting、idempotency、conflict、version差、autofixのbehavior changeをtestします。',
    (30, 'Code Generation・Scaffolding'): 'code generationはschema/IDL/modelから反復codeを作り、scaffoldはproject初期構造を生成します。text templateは単純、AST transformは構文を保った変更に向きます。generated/manual ownership、regeneration、format、diff、custom extension point、migration、version互換性を明確にします。',
    (30, 'CLI・TUI Design'): 'CLIはstdin/stdout/stderrとexit codeを安定contractにし、human向け色表示とmachine向けJSONを分けます。subcommand、flag、environment、configのprecedenceを一貫させます。TUI/interactive modeでもnon-interactive、dry-run、confirm、cancel、signal、progress、idempotencyを維持します。',
    (30, 'Package Manager・Dependency'): 'package managerはversion constraintからdependency graphを解決し、lockfileで具体version/integrityを固定します。workspaceはlocal packageを一体管理し、cache/storeで重複download/buildを減らします。peer/optional/platform dependency、script security、registry、license、update policyを運用します。',
    (30, 'Local Development Environment'): 'one-command setupはtoolchain、service、data、secret、port、migrationを再現します。dev container/VM、Docker compose、emulator、mockをproductionとの差が見える形で使います。seed、reset、offline、debug、resource requirement、architecture差、credential expiryをdocument/testします。',
    (30, 'Internal Developer Platform・AI Coding'): 'platform portalはservice catalog、template、environment、docs、ownership、scorecardを統合します。AI coding agentにはrepository context、allowed tool、test、review、secret boundary、auditを与え、生成量ではなくaccepted changeとdefectで評価します。golden pathとescape hatchを両立します。',

    # 31 Product Engineering
    (31, 'Problem Discovery'): 'interviewでは希望機能をそのまま要件にせず、直近の具体行動、代替手段、頻度、cost、感情、triggerを聞きます。観察とusage dataで発言との差を確認し、JTBDで状況・進歩・制約を整理します。solutionを固定する前にproblem evidenceと対象segmentを明確にします。',
    (31, 'Requirement Engineering'): 'stakeholderごとのgoalとconstraintを集め、functional、quality attribute、business rule、compliance、assumptionへ分けます。acceptance criteriaは観測可能な例、non-functionalは負荷・failure・security条件を数値化します。conflict、priority、traceability、change reason、out-of-scopeを残します。',
    (31, 'Domain Modeling Workshop'): 'Event Stormingは過去形domain eventからcommand、actor、policy、aggregate、external systemを発見します。Example Mappingはrule、example、questionでstoryの曖昧さを減らします。workshopの成果は綺麗な付箋ではなく、共通言語、boundary、未解決question、実装/test例へ移します。',
    (31, 'Product Metric'): 'north-star metricは長期user valueを代表し、input metricはteamが動かせる先行signalです。funnelはstep間drop、cohort retentionは同時期userの継続を追います。metric定義、denominator、window、bot/internal除外、guardrail、segmentを一元化し、数字を目的化しません。',
    (31, 'Experiment・A/B Test'): 'experimentは対象populationをrandom assignmentし、controlとの差からcausal effectを推定します。primary metric、guardrail、sample size、duration、stopping ruleを事前登録します。novelty、interference、multiple test、peeking、SRM、practical significanceを検査し、定性feedbackも解釈に使います。',
    (31, 'Prioritization・Roadmap'): 'priorityはimpact、confidence、effort、risk、dependency、learning value、option valueを比較します。roadmapを固定feature日程だけにせず、outcome、hypothesis、milestone、decision pointで表します。uncertaintyの高い項目はdiscovery/prototypeを先にし、sunk costではなく新しい証拠で更新します。',
    (31, 'Technical Product Decision'): 'build/buyではlicense feeだけでなくintegration、data control、lock-in、security、latency、operation、exit costを比較します。platform投資は複数productへ再利用されるleverageとadoption costを測ります。architecture runwayは未知未来を作り込まず、次の重要optionを開く最小基盤へ投資します。',
    (31, 'Delivery・Scope Control'): 'MVPは機能が少ない製品ではなく、最重要仮説を実利用で検証する最小end-to-end sliceです。vertical sliceでUIからdataまで価値を通し、feature flagで段階releaseします。definition of doneにtest、telemetry、security、docs、support、rollbackを含めます。',
    (31, 'Feedback・Analytics・Iteration'): 'event instrumentationはuser/action/object/result/contextをschema化し、analysis questionから設計します。cohort、funnel、session replay、support/sales voice、interviewを組み合わせます。correlationから仮説を作り、experimentや自然実験で検証し、学習をdecision logへ残します。',
    (31, 'Ethics・Accessibility・Sustainability'): 'inclusive designは平均userだけでなく、障害、言語、年齢、device、network、situational limitationを考慮します。dark patternや依存を促すmetric最適化を避け、consentとcontrolを提供します。energy、hardware、data retention、運用者負担、廃止時移行をproduct lifecycleのcostに含めます。',

    # 32 Leadership
    (32, 'Technical Leadershipの役割'): 'technical leaderは最難codeを独占するのではなく、目的、constraint、decision principleを共有し、teamが自律して良い判断を増やします。unknownとriskを早期に可視化し、重要境界へ深く入り、他はdelegateします。成果は自分のoutputではなくsystem/teamの持続的なthroughputとqualityです。',
    (32, 'Architecture・Design Review'): 'reviewはsolutionを否定する場ではなく、problem、requirement、assumption、option、trade-off、failure、operationを共同検証します。質問を先にし、重大riskと好みを分けます。decision ownerを明確にし、ADR、follow-up experiment、期限付きrisk acceptanceへ落とします。',
    (32, 'Code Review'): 'code reviewはcorrectness、security、maintainability、test、operability、knowledge sharingを目的にします。blocking issue、suggestion、questionを区別し、人格ではなくartifactへ具体的feedbackを出します。大PRを避け、automationでstyleを除き、review latencyとdefect escapeを改善します。',
    (32, 'Planning・Estimation・Risk'): 'estimateは不確実性を一数字へ隠さず、range、confidence、assumption、dependencyで表します。milestoneは価値/学習が検証できる状態、risk registerはprobability、impact、trigger、mitigation、ownerを持ちます。critical pathとbufferを見て、scope/time/resourceのtrade-offを早期に共有します。',
    (32, 'Team Topology・Ownership'): 'stream-aligned teamはuser value flow、platform teamは共通能力、enabling teamは専門支援、complicated-subsystem teamは高度componentを担います。ownershipにはbuildだけでなくSLO、on-call、security、cost、deprecationを含めます。cognitive loadとcommunication pathをsystem boundaryへ反映します。',
    (32, 'Hiring・Onboarding・Growth'): 'structured interviewはrole competencyごとに同じquestion/rubricを使い、signalとbiasを管理します。onboardingはaccess、environment、domain、people、small production changeを段階化します。career ladderはimpact、scope、autonomy、collaboration、technical depthを例示し、titleより成長feedbackへ使います。',
    (32, 'Communication・Conflict・Decision'): 'written contextは目的、背景、data、option、decision requestを非同期で共有します。conflictでは立場でなく利害・仮定を分け、disagree-and-commit条件とescalation pathを定めます。DRI/RACIは責任を明確にしますが、相談と情報共有を止めないようにします。',
    (32, 'Operational Leadership'): 'leaderはon-call burden、incident role、production access、readinessをteam能力として整えます。重大incidentではimpact縮小とclear communicationを優先し、個別実装へ入りすぎずdecision/coordinationを支えます。risk acceptanceはowner、期限、monitoring、fallback、事業承認を明示します。',
    (32, 'Strategy・Portfolio・Technical Debt'): 'technical strategyはbusiness differentiation、scale、risk、team capabilityから数年の方向とguardrailを示します。portfolioではfeature、reliability、security、platform、debt、researchをoption価値とopportunity costで配分します。technical debtを項目、interest、trigger、repayment pathで管理します。',
    (32, 'Culture・Learning・Change'): 'psychological safetyは反対、質問、失敗共有が罰されない環境で、accountabilityと両立します。retrospectiveは具体event、pattern、experimentへ繋げ、同じactionを放置しません。community of practice、pairing、internal talk、rotationで知識を分散し、changeはsmall pilotとfeedbackで広げます。',

    # 33 Browser / Frontend
    (33, 'Browser Architecture'): '現代browserはbrowser process、renderer、network、GPU等を分離し、site isolationとsandboxで侵害範囲を抑えます。rendererはHTML/CSS/JSを処理しますが、process間IPCとsecurity policyを介してOS resourceへアクセスします。tab数、cross-origin iframe、extensionがprocess modelとmemoryへ影響します。',
    (33, 'Navigation・Resource Loading'): 'navigationはURL解析、DNS、connection/TLS、HTTP、response sniffing、document creationを経ます。parserはHTMLを読みながらresourceを発見し、preload scannerが先読みします。cache、preconnect、preload/prefetch、priority、CORS、redirect、service workerをwaterfallで分析します。',
    (33, 'DOM・Event'): 'DOMはdocumentをnode treeとして公開し、mutationがstyle/layoutへ影響します。eventはcapture→target→bubbleで伝播し、default actionとpropagation停止を区別します。event delegationは多数listenerを減らし、custom element/shadow DOMはencapsulationとaccessibilityを考慮します。',
    (33, 'CSS・Layout'): 'cascadeはorigin、importance、layer、specificity、source orderでpropertyを決め、inheritanceが子へ伝えます。box modelとnormal flow、flex、gridがsize/positionを計算します。intrinsic size、overflow、stacking context、containment、container queryを理解すると予期しないlayoutを診断できます。',
    (33, 'Rendering Pipeline'): 'browserはDOM/CSSOMからstyleを計算し、layoutでgeometry、paintでdraw command、compositeでlayerを合成します。layout-triggering readとwriteを交互に行うとforced synchronous layoutが起きます。transform/opacityはcompositorで処理しやすい一方、layer過多はmemoryを使います。',
    (33, 'Frontend Architecture'): 'componentはviewだけでなくstate ownership、event、data dependency、error/loading境界を持ちます。server stateとlocal UI stateを分け、unidirectional data flowで更新経路を追跡可能にします。routing、form、cache、optimistic update、permission、feature flagをdomain/module境界に配置します。',
    (33, 'Web Performance'): 'navigation/resource/render/runtimeの各段でLCP、INP、CLS等のuser-centric signalを改善します。JavaScript bundleをsplitし、critical CSS、responsive image、font strategy、cache/CDNを使います。main-thread long task、hydration、third-party script、memory leakをreal-user monitoringとprofileで追います。',
    (33, 'Accessibility'): 'semantic HTMLはrole/name/stateをaccessibility treeへ提供し、keyboard focus orderとvisible focusを守ります。label、heading、landmark、alternative text、color contrast、reduced motionを扱います。screen reader/keyboard実機testとautomated checkを組み合わせ、dynamic updateは適切なannouncementを設計します。',
    (33, 'Web Security'): 'same-origin policyは異origin documentのdata accessを制限し、CORSはserverが一部cross-origin readを許可します。CSP、Trusted Types、safe sinkでXSSを抑え、SameSite/CSRF tokenでstate-changing requestを守ります。iframe sandbox、postMessage origin、storage、dependencyをtrust boundaryとして扱います。',
    (33, 'PWA・Offline・Edge'): 'service workerはnetwork proxyとしてrequestをinterceptし、cache-first/network-first等を実装します。offline mutationはqueueし、再接続時にidempotent syncとconflict解決を行います。installabilityやpushを価値に合わせ、stale asset、service worker update、storage quota、edge renderingのpersonalized cacheを管理します。',

    # 34 Mobile / Desktop
    (34, 'Client Platform Architecture'): 'mobile/desktop OSはappをsandboxed processで実行し、foreground/background/suspended/terminatedのlifecycleを管理します。permissionとentitlementがdevice/resource accessを制限します。background時間、memory pressure、window/scene、process kill後のstate restorationを前提にします。',
    (34, 'Native UIとDeclarative UI'): 'declarative UIはstateからview treeを再計算し、frameworkが差分更新します。SwiftUI/Composeではstate ownershipとidentityが再描画・lifecycleを決め、imperative APIとのbridgeが必要です。layout constraint、animation、accessibility、platform conventionをnative behaviorに合わせます。',
    (34, 'Navigation・State・Data Flow'): 'screen graphはpush/modal/tab/deep linkを一貫model化し、back behaviorとstate restorationを定義します。unidirectional flowはevent→state update→renderで追跡可能にします。global stateを増やさず、screen/domain/session scopeとdependency injectionを分けます。',
    (34, 'Local Storage・Offline First'): 'SQLiteはstructured relational data、fileはblob、keychain/keystoreはsmall secretへ使います。offline-firstではlocal DBをUI source of truthにし、sync queueがserverと収束させます。version、migration、conflict、tombstone、clock、partial sync、encryption、backupを設計します。',
    (34, 'Network・Background Task'): 'client HTTPはconnectivity変化、radio cost、app suspension、retry、cacheを扱います。background transfer/taskはOSが実行時期と時間を制限するため、checkpointとidempotencyが必要です。push notificationはdata同期のsignalとして使い、機密dataをpayloadへ入れません。',
    (34, 'Device・OS Integration'): 'camera、microphone、location、sensor、share/intents、notificationはOS APIとpermissionへ従います。permission requestは利用文脈で説明し、denied/restricted/limitedを扱います。hardware absence、orientation、interrupt、privacy indicator、background restriction、data retentionをtestします。',
    (34, 'Cross-platform Architecture'): 'cross-platformではdomain/core、network、storage等を共有し、UI/OS integrationをnativeに残す境界を選びます。Flutter/React Native等のruntime/bridge、Rust/FFI shared coreはbuild、debug、memory、async、errorのboundary costを持ちます。platform capabilityを最低共通分母へ落としすぎないことが重要です。',
    (34, 'Performance・Battery・Memory'): 'UIはframe budget内にlayout/drawを終え、main threadをblockしない必要があります。startupをcold/warm、memoryをallocation/retention、energyをCPU/GPU/network/location/wakeupで測ります。background pollingをpush/eventへ、large imageをdownsampleし、memory pressureでcacheを解放します。',
    (34, 'Security・Privacy'): 'secretはkeychain/keystore、sensitive fileはplatform data protection、communicationはTLSとserver validationを使います。certificate pinningはrotation/outage riskを伴うためthreatに応じます。biometricはlocal user presenceの確認で、server identityの代替ではありません。screenshot、clipboard、backup、log、deep linkを守ります。',
    (34, 'Testing・Distribution・Release'): 'unit、snapshot、UI、integration、device testを分け、simulatorだけでなく実deviceのcamera、battery、network、performanceを確認します。signing/provisioning、store review、privacy manifest、symbol、crash reportを管理します。phased rollout、remote flag、minimum version、rollback不能migrationへ備えます。',

    # 35 Embedded / IoT
    (35, 'Electronics・Digital Interface'): 'voltageは電位差、currentは電荷流、resistorで電流を制限します。GPIO inputはfloatingを避けpull-up/downを使います。I2Cはaddressed shared bus、SPIはclocked full-duplexでchip select、UARTは非同期serialで、電圧level、timing、termination、logic analyzerを扱います。',
    (35, 'MCU Architecture'): 'MCUはCPU、flash、SRAM、timer、ADC、communication peripheralを一chipに持ちます。memory-mapped registerのbitでdeviceを制御し、interrupt vectorからhandlerを実行します。clock tree、watchdog、DMA、stack、boot sequence、critical section、interrupt latencyをdatasheetから読みます。',
    (35, 'Embedded C・Rust'): 'embedded Cではvolatile register、pointer、bit mask、linker script、undefined behaviorを扱います。Rust no_stdは標準OS runtimeなしでcoreを使い、ownershipでbuffer/peripheralの二重利用を防げます。allocationを避け、panic、interrupt safety、static initialization、FFI、binary size、timingを検証します。',
    (35, 'RTOS'): 'RTOSはpriority-based task schedule、queue、semaphore、timerを提供し、deadlineを満たす予測可能性を重視します。priority inversionにはinheritance/ceiling、ISRは短くしてtaskへworkを渡します。stack size、tick、jitter、blocking、watchdog、worst-case execution timeを測ります。',
    (35, 'Sensor・Actuator'): 'sensorは物理量を電気signalへ変換し、ADC sampling、calibration、bias、drift、noiseを扱います。actuatorはmotor、relay、LED等へ出力し、driver、flyback、PWM、安全limitが必要です。unit、coordinate、timestamp、saturation、fault detection、closed-loop feedbackを設計します。',
    (35, 'IoT Networking'): 'BLEは低電力短距離、Wi-Fiは高bandwidth、MQTTはbroker型軽量pub/subです。connection、advertising、sleep、reconnect、QoS、retain、topic、payload schemaをbattery/network条件へ合わせます。gatewayを使う場合、device identity、offline buffer、protocol translation、fleet boundaryを定義します。',
    (35, 'Power Management'): 'average energyはactive current×duty cycleとsleep current、radio/sensor wakeupで決まります。deep sleepではRAM/peripheral/clockが失われる場合があり、wake sourceとstate restoreを設計します。battery chemistry、voltage curve、regulator efficiency、brownout、temperatureを測定器でprofileします。',
    (35, 'Device Security'): 'secure bootはtrusted keyで署名検証したfirmwareだけを起動し、hardware root of trustとrollback protectionを使います。deviceごとのidentity/keyをsecure element等へ保存し、factory provisioningとrotationを管理します。debug port、physical extraction、fault injection、default credential、local networkを脅威へ含めます。',
    (35, 'OTA・Fleet Management'): 'OTAはsigned artifactを段階配信し、download検証、A/B slot、health check、rollbackでbrickを防ぎます。fleetはmodel/hardware/firmware/config cohortを追跡し、canaryとpause条件を設けます。offline device、partial update、schema互換、telemetry、remote command auditを管理します。',
    (35, 'Edge AI・Edge Architecture'): 'on-device inferenceはlatency、privacy、offline性を改善しますが、memory、compute、power、thermal制約があります。quantizationとsmall model、feature extraction、acceleratorを使い、cloud/gateway/deviceへ処理を分割します。model update、drift、sensor calibration、fallback、安全limitをfleet運用へ統合します。',

    # 36 Robotics
    (36, 'Robotics System Overview'): 'robotはsensorで環境と自己状態を観測し、planner/controllerがactionを決め、actuatorが物理世界へ作用するsense-plan-act loopです。coordinate frame、timestamp、rate、latency、uncertaintyを全componentで一貫させます。real-time safety loopと高level AI loopを分離し、fail-safeを独立させます。',
    (36, 'Kinematics'): 'poseはpositionとorientationで、homogeneous transformがframe間変換を合成します。forward kinematicsはjoint angleからend-effector pose、inverseは目標poseからjointを求め、複数解/解なしがあります。Jacobianはjoint速度とCartesian速度を結び、singularityでrankを失います。',
    (36, 'Dynamics'): 'dynamicsはmass/inertia、Coriolis、gravity、frictionとforce/torqueからaccelerationを求めます。inverse dynamicsは目標motionに必要なtorqueを計算します。model error、payload、backlash、complianceを考慮し、simulationとsystem identificationでparameterを合わせます。',
    (36, 'Classical Control'): 'feedback controlは測定値と目標のerrorから入力を調整します。PIDのPは現在error、Iは累積offset、Dは変化率を補正しますが、noise、saturation、integral windupを扱います。stability、rise time、overshoot、steady-state error、frequency responseを測りtuneします。',
    (36, 'State Estimation'): 'Bayes filterはprior、motion model、measurement likelihoodからposteriorを更新します。Kalman filterはlinear Gaussian、EKF/UKFは非線形近似、particle filterはsample集合で多峰性を表します。observability、covariance、bias、outlier、initialization、divergenceを検証します。',
    (36, 'Sensor Fusion'): 'IMUは高rateだがdrift、cameraはrichだがlighting、LiDARはgeometryに強い等、sensorごとに誤差が違います。timestamp synchronization、extrinsic/intrinsic calibration、frame transform、latency補償がfusionの前提です。故障sensorのoutlier rejectionとdegraded modeを設計します。',
    (36, 'Path・Motion Planning'): 'path planningはconfiguration spaceでcollision-free経路、trajectoryは時間・速度・加速度constraintを加えます。A*/Dijkstraはgraph search、RRT/PRMは高次元空間をsamplingします。dynamic obstacle、kinodynamic constraint、cost map、replanning、smoothness、安全marginを扱います。',
    (36, 'SLAM・Localization'): 'SLAMはmotion/observationからrobot poseとmapを同時推定します。front-endがfeature/scan matching、back-endがpose graph optimization、loop closureが累積driftを補正します。data association、dynamic object、scale、map representation、relocalization、ground truth評価が難所です。',
    (36, 'Robot Learning・Physical AI'): 'imitation learningはdemonstration、reinforcement learningはrewardからpolicyを学びます。world modelはactionによる状態変化を予測しplanningへ使います。simulationでdataを増やしてもsim-to-real gapがあり、domain randomization、offline data、安全constraint、uncertainty、人介入を組み込みます。',
    (36, 'Safety・Deployment・Human Interaction'): 'physical systemはsoftware errorが人身・設備damageへ繋がるため、hazard analysis、speed/force limit、emergency stop、redundant sensing、safe stateを独立層で実装します。human-robot interactionでは意図表示、予測可能性、handover、privacy、teleoperationを設計し、現場scenarioでvalidationします。',

    # 37 GPU / HPC
    (37, 'Parallel Computer Architecture'): 'CPUは低latencyと複雑control、GPUは多数laneでthroughputを重視します。SIMTではwarp/wavefront内threadが同instructionを実行し、branch divergenceで効率が下がります。memory hierarchyとschedulerが大量threadでlatencyを隠すため、parallelismとworking setを用意します。',
    (37, 'GPU Programming Model'): 'kernelをgrid of block/threadとして起動し、thread indexからdata範囲を決めます。block内はshared memoryとbarrierで協調できますが、block間同期は通常kernel boundary等が必要です。block size、register、shared memoryがoccupancyと同時resident block数を決めます。',
    (37, 'GPU Memory Optimization'): 'global memory accessはwarp内addressをcoalescingすると少ないtransactionで済みます。shared memoryは高速scratchpadですがbank conflict、register過多はoccupancy低下、host-device copyはPCIe等のcostがあります。tiling、pinned memory、async copy、data reuseでbandwidthを節約します。',
    (37, 'Numerical Computing'): 'floating pointは有限precisionで、加算順、cancellation、overflow/underflowが結果を変えます。BLASはvector/matrix operationの標準interfaceで高度最適化libraryを利用できます。condition number、stable algorithm、mixed precision、reduction order、reproducibilityを確認します。',
    (37, 'Kernel Optimization'): 'tilingはdataをfast memoryへ分割reuseし、fusionはintermediate write/readとlaunchを減らします。vectorized load、unroll、occupancy、instruction mixをprofileします。単一kernel最速ではなく、end-to-end graphのtransfer、synchronization、batch、tailを含めて最適化します。',
    (37, 'Accelerator Compiler'): 'graph compilerはmodel/operator graphをIRへ変換し、shape/type推論、fusion、layout、scheduling、kernel selectionを行います。loweringで高level operationをtarget instructionへ段階変換します。dynamic shape、fallback、autotune、compile cache、numerical equivalence、hardware portabilityを扱います。',
    (37, 'Distributed HPC'): 'MPIはprocess間point-to-pointとbroadcast/reduce等collectiveを提供します。domain decompositionでdataをnodeへ分け、halo exchangeとcomputeをoverlapします。network topology、message size、latency/bandwidth、load balance、synchronization、checkpoint/restartがscale効率を決めます。',
    (37, 'Distributed Deep Learning'): 'data parallelはbatch、tensor parallelはlayer内tensor、pipeline parallelはlayer群をdeviceへ分割します。all-reduceとactivation/parameter通信、pipeline bubble、optimizer state memoryがbottleneckです。checkpointing、gradient accumulation、sharding、fault recovery、numerical consistencyを設計します。',
    (37, 'Performance Model'): 'roofline modelはarithmetic intensityとcompute/memory bandwidth上限からkernelがcompute-boundかmemory-boundかを示します。Amdahlは固定problemのserial比、Gustafsonはproblem size拡大時のscaleを考えます。profile counterとmodel差から、次に最適化すべきresourceを決めます。',
    (37, 'HPC Reliability・Scheduling・Cost'): 'job schedulerはnode/GPU/memory/timeをrequestに割り当て、queue、priority、reservation、preemptionを管理します。大規模runはnode failure確率が上がるためcheckpoint、elastic/restartを用意します。utilizationだけでなくwait time、energy、data transfer、license、failed run、developer timeをcostへ含めます。',

    # 38 Signal / Wireless
    (38, 'Signal・Sampling'): 'continuous signalをsampling periodごとの離散値へ変換し、amplitudeをquantizeします。Nyquist条件を満たさない高周波成分は低周波へaliasするため、sampling前にanti-alias filterを使います。resolution、dynamic range、clock jitter、missing sample、unitとtimestampを管理します。',
    (38, 'Fourier・Frequency Domain'): 'Fourier transformはsignalをfrequency成分の振幅・位相へ分解し、DFTをFFTで効率計算します。time-domain convolutionはfrequency-domain multiplicationに対応します。有限windowではspectral leakageが起きるためwindow functionとresolution、zero padding、stationarityを理解します。',
    (38, 'Digital Filter'): 'FIRは有限impulse responseでlinear phaseを作りやすく常に安定、IIRはfeedbackで少ない係数でも鋭いresponseを得ますが安定性に注意します。cutoff、transition band、ripple、phase delay、orderを要件から設計し、fixed-point quantizationとreal-time costを確認します。',
    (38, 'Statistical Signal Processing'): 'noiseを確率processとしてmodel化し、correlationとpower spectral densityで構造を見ます。estimationはparameter/state、detectionはsignal有無をthresholdで判断し、false alarmとmissのtrade-offを持ちます。matched filter、maximum likelihood、Bayesian estimatorをSNRとpriorに応じて使います。',
    (38, 'Audio・Speech Signal'): 'STFTは短いwindowごとにspectrumを計算し時間-frequency変化を表します。mel scaleは人の知覚に近いfrequency spacingで、speech featureへ使われます。beamformingはmicrophone arrayのdelay/phaseを揃え特定方向を強め、echo cancellationはspeaker経路を推定して除去します。',
    (38, 'Wireless Communication'): 'digital modulationはbitをamplitude/phase/frequency symbolへ写し、channelはpath loss、noise、fading、interferenceを加えます。SNRとbandwidthがcapacity/BERを左右し、error-correcting codeとinterleavingで復元力を上げます。link budget、latency、spectrum、power、regulationを設計します。',
    (38, 'OFDM・MIMO'): 'OFDMはbandwidthを多数のorthogonal subcarrierへ分け、cyclic prefixでmultipathのinter-symbol interferenceを抑えます。channel estimationで各subcarrierのamplitude/phaseを補正します。MIMOは複数antennaでspatial diversity/multiplexingを行い、CSI、rank、beamforming、同期が性能を決めます。',
    (38, 'Wi-Fi・CSI Sensing'): 'CSIは各subcarrier/antenna pathのcomplex channel responseを表し、人の動きや呼吸がmultipathのamplitude/phase/Dopplerを変えます。packet timing、CFO/SFO、phase offset、environment変化、device差をcalibrateし、filter/window/feature/modelで推定します。privacy、false alarm、複数人、壁、再配置へのrobustnessを評価します。',
    (38, 'Radar・Localization'): 'time-of-flightは往復時間から距離、FMCWはchirp送受信差frequencyからrange、連続chirp間phaseからvelocityを求めます。antenna arrayの位相差でangleを推定します。range-Doppler/angle FFT、clutter removal、CFAR、multipath、resolution、ambiguityを扱います。',
    (38, 'Signal ML・Edge Deployment'): 'signal MLではfilter/normalization/segmentationからspectrogramやstatistical featureを作り、CNN/Transformer等へ入力します。data splitは人・場所・device・時間を跨いでleakageを防ぎます。edgeではstreaming buffer、latency、memory、quantization、drift、sensor failure、confidenceとfallbackを実装します。',
})

CONCEPT_NOTES: dict[str, str] = {
    'V8': 'Googleが開発するJavaScript/WebAssembly engineで、parser、bytecode interpreter、JIT compiler、garbage collectorを含みます。Node.jsではJavaScriptの実行とheap管理を担います。',
    'libuv': 'Node.jsが利用するcross-platform I/O libraryです。event loop、network readiness、timer、thread pool、process・signal処理をOS差から抽象化します。',
    'event loop': 'readyになったI/O、timer、callbackをphaseごとに取り出して実行するloopです。callbackが長時間CPUを占有すると、他requestの処理開始が遅れます。',
    'thread pool': '複数worker threadへblockingまたはCPU処理を割り当てる仕組みです。queueが詰まると非同期APIでも待ち時間が増えます。',
    'structural typing': '型名ではなく必要なpropertyやmethodの形が一致するかで互換性を判断する方式です。',
    'conditional type': 'T extends U ? X : Y のように型関係を条件として結果型を選ぶTypeScriptの型演算です。unionへ分配される条件も理解が必要です。',
    'mapped type': 'key集合を反復して各propertyの型やreadonly/optional属性を変換するTypeScriptの型演算です。',
    'infer': 'conditional typeのpattern内で型の一部分を新しい型変数として取り出すTypeScript keywordです。',
    'decorator semantics': '宣言へ追加処理を関連付ける規則です。legacy TypeScript decoratorと標準decoratorでは評価・置換・metadataの扱いが異なります。',
    'Reflect metadata': 'classやmethod等へkey-value metadataを関連付け、runtimeで取得する仕組みです。DIやroute discoveryで利用されます。',
    'ownership': '値の解放責任を一つのownerへ結びつけ、scope終了時に自動解放するRustの資源管理modelです。',
    'goroutine': 'Go runtimeがOS thread上へ多重化する軽量な実行単位です。作成は容易ですが、終了条件とleak防止が必要です。',
    'channel': 'goroutine間で値を送受信し、所有権移動や同期点を表せるtyped queueです。',
    'MVCC': '複数versionのrowを保持し、readerとwriterの競合を減らしながらtransactionごとのsnapshotを提供する方式です。',
    'WAL': 'data pageを更新する前に変更記録を順序付きlogへ永続化し、crash recoveryとreplicationへ利用する仕組みです。',
    'idempotency': '同じ操作を複数回実行しても、1回実行した場合と同じ最終効果になる性質です。',
    'bounded context': '特定のdomain modelと言語が一貫して有効な境界です。境界外では同じ語が別の意味を持ち得ます。',
    'aggregate': '一つのtransactionで不変条件を守るentity/value objectのclusterで、外部変更はrootを経由します。',
    'dependency rule': 'source code dependencyをbusiness rule側へ向け、外部frameworkやDBの変更が内側へ波及しにくくする規則です。',
    'SLI': 'ユーザー体験に関係する信頼性を実測するindicatorです。成功率、latency、freshness等をevent比率や分布で表します。',
    'SLO': '一定期間にSLIが満たすべき目標値です。error budgetとrelease判断の基準になります。',
    'error budget': 'SLOが許容する失敗量です。残量に応じてfeature速度と信頼性改善の優先度を調整します。',
    'XSS': '未信頼dataがHTML/JavaScriptとして解釈され、利用者のbrowser上で攻撃codeが実行される脆弱性です。',
    'CSRF': 'browserがcookie等を自動送信する性質を利用し、利用者の意図しないstate-changing requestを送らせる攻撃です。',
    'SSRF': 'serverに攻撃者指定の宛先へrequestさせ、内部networkやmetadata service等へ到達する攻撃です。',
    'JWT': '署名付きclaimをcompactに表現するtoken形式です。暗号化ではなく、issuer・audience・expiry・algorithm等の検証が必要です。',
    'precision': '陽性と予測したもののうち、実際に陽性だった割合です。false positiveのcostが高い場合に重視します。',
    'recall': '実際の陽性のうち、modelが陽性として捕捉した割合です。false negativeのcostが高い場合に重視します。',
    'self-attention': 'sequence内の各位置が他位置との関連度を計算し、情報を重み付き集約するmechanismです。',
    'KV cache': 'autoregressive生成で過去tokenのkey/valueを保存し、次tokenごとの再計算を減らすcacheです。',
    'RAG': '外部sourceから関連情報を検索し、そのevidenceをcontextへ加えて生成をgroundするarchitectureです。',
    'prompt injection': 'modelが読む未信頼contentに悪意あるinstructionを混ぜ、上位instructionやtool policyを逸脱させる攻撃です。',
    'B+tree': '内部nodeにseparator key、leafにsorted entryを持つ平衡多分木で、range scanとdisk page単位のindexに適します。',
    'TCP': '順序付きで信頼できるbyte streamを提供し、再送、flow control、congestion controlを行うtransport protocolです。',
    'UDP': 'connection確立なしに独立datagramを送るtransport protocolで、信頼性や順序はapplication側で必要に応じて実装します。',
    'TLS': 'network上の盗聴・改ざん・なりすましを防ぐため、相手認証と暗号化channelを確立するprotocolです。',
    'JIT': '実行時の情報を使ってhot codeをnative codeへcompileする方式です。仮定が崩れた場合のdeoptimizationが必要です。',
    'GC': 'programから到達不能になったmemoryを自動回収するruntime機能です。pause、throughput、memory overheadのtrade-offがあります。',
}

